    "explanation": "【核心考點】品質管理系統架構與品質手冊之制定依據。\n【正確答案說明】(B) 品質手冊（Quality Manual）是企業內部界定品質政策、組織架構、管理程序與品質目標的綱領性指引文件，其制定主要是依據「公司內部的品質管理需求」（符合 ISO 9001 / IATF 16949 等品質管理架構）。\n【選項辨析】\n- (A) IPC 國際規範：屬於產品技術、製造與允收標準（如 IPC-6012、IPC-A-600），而非公司品質管理系統手冊之直接編制依據。\n- (B) 公司內部的品質管理需求：正確。品質手冊乃企業內部建立並維持品質保證體系的頂層最高指導原則文件。\n- (C) 依客戶的品質規範要求：客戶規範通常列於合約、圖面或特定工程規範中，由二階/三階作業程序書或品管計畫書（Quality Plan）落實，非整本品質手冊的主要依據。\n- (D) 公司和客戶共同討論：品質手冊由組織自主建立與核准發布，非與單一客戶共同討論制定。",
