    "stem": "壓合用的膠片(Prepreg)如需存放一個月再使用，其儲存環境的溫度應控制在多少 oC 左右？",
    "question": "壓合用的膠片(Prepreg)如需存放一個月再使用，其儲存環境的溫度應控制在多少 oC 左右？",
    "options": [
      "零下5oC ~ 零下10oC",
      "5～10oC",
      "10～20oC",
      "22～24oC"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】膠片（Prepreg, 半固化片）之儲存條件與壽命管控。\n【正確答案說明】(B) 膠片（Prepreg）為 B-stage 半固化環氧樹脂，在室溫下會緩慢進行交聯硬化反應。為維持樹脂流動度並存放一個月（30天），標準環境溫度通常須嚴格控制於低溫冷藏環境「5～10°C」（或 < 5°C / 5~10°C），且相對濕度須 < 50% RH，使用前須經足夠時間回溫以防吸濕水氣。\n【選項辨析】\n- (A) 零下5oC ~ 零下10oC：屬於極低溫冷凍（如某些特殊黏著劑或預浸材），一般 PCB 環氧樹脂膠片存放於 5~10°C 即可維持 1~3 個月活性，不需過度冷凍避免脆化與回溫過慢。\n- (B) 5～10oC：正確。PCB 產業標準標準冷藏庫溫度為 5~10°C（一般可保存一個月以上）。\n- (C) 10～20oC：此溫度範圍樹脂反應速度仍稍高，保存期會大幅縮短至數天至一週。\n- (D) 22～24oC：此為常溫潔淨室溫度，膠片在常溫下的保存期通常僅有幾天至一週以內。",
