    "explanation": "【核心考點】IPC 規範架構中剛性/硬式多層電路板標準代號。\n【正確答案說明】(C) IPC-6012（Qualification and Performance Specification for Rigid Printed Boards）為業界公認之「剛性（硬式）印刷電路板資格與性能規範」。\n【選項辨析】\n- (A) IPC-6010：為印刷板系列規範的總綱（Overview / Series Framework）。\n- (B) IPC-6011：為一般印刷電路板通用性能規範（Generic Performance Specification for Printed Boards）。\n- (C) IPC-6012：正確。為硬式電路板（Rigid Printed Boards）的專屬規範。\n- (D) IPC-6013：為軟性印刷電路板（Flexible Printed Boards）的資格與性能規範。",
