    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】印刷電路板外觀檢驗與允收標準規範。\n【正確答案說明】(A) IPC-A-600（Acceptability of Printed Boards）以大量顯微切片彩色圖片及文字詳細定義了裸板各項外觀與內部微結構的可接受（Acceptable）、目標（Target）與拒收（Nonconforming）條件。\n【選項辨析】\n- (A) IPC-A-600：正確。是以圖文形式描述裸電路板外觀與切片允收性之標準。\n- (B) IPC-A-601：無此標準（相關規範為 6010 系列）。\n- (C) IPC-A-610：為電子組裝（Electronic Assemblies / PCBA）焊接後的外觀允收標準，而非裸板標準。\n- (D) IPC-A-612：非現行主要電路板檢驗規範。",
