    "stem": "品管七大手法中，依缺點類別及其所佔百分比排序的品管圖為何？",
    "question": "品管七大手法中，依缺點類別及其所佔百分比排序的品管圖為何？",
    "options": [
      "特性要因圖",
      "直方圖",
      "柏拉圖",
      "層別圖"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】QC 七大手法中柏拉圖（Pareto Diagram）之定義與特徵。\n【正確答案說明】(C) 柏拉圖（Pareto Diagram）是根據「80/20 法則」，將搜集到的缺點數據依不良項目出現頻率或損失金額「由大到小排序繪製柱狀圖」，並疊加「累積百分比折線」，用以找出關鍵少數之重要不良項目。\n【選項辨析】\n- (A) 特性要因圖：又稱魚骨圖，用於系統化分析造成某結果的多方面潛在原因。\n- (B) 直方圖：用於呈現計量數據的分配形態、集中趨勢與離散程度。\n- (C) 柏拉圖：正確。依缺點類別及百分比排序，找出「關鍵的少數、次要的多數」。\n- (D) 層別圖：將數據按人、機、料、法、環等不同維度分門別類加以分析。",
