    "stem": "品質成本包含有四大項成本，下列何項的品質成本最高昂？",
    "question": "品質成本包含有四大項成本，下列何項的品質成本最高昂？",
    "options": [
      "內部失敗成本",
      "外部失敗成本",
      "鑒定成本",
      "預防成本"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】品質成本（Cost of Quality, COQ）四大結構及其影響程度。\n【正確答案說明】(B) 品質成本分為：預防成本、鑑定成本、內部失敗成本、外部失敗成本。當不合格品流出至客戶端甚至市場終端時，會導致客訴退貨、罰款、召回賠償、公司商譽與市場訂單損失，因此「外部失敗成本（External Failure Cost）」的代價通常最為慘重且高昂。\n【選項辨析】\n- (A) 內部失敗成本：在出貨前於廠內發生的重工、報廢成本，雖然有損失但避免了市場災難。\n- (B) 外部失敗成本：正確。產品流入市場引發的退貨、商譽損失、法律責任代價最高。\n- (C) 鑒定成本：日常檢驗、量測與測試費用，屬於受控之評估成本。\n- (D) 預防成本：製程設計、教育訓練、品質工程規劃等事前投入，成本最低且效益最高。",
