    "pdf_num": 9,
    "stem": "某家電路板廠有3條鍍金設備同時生產，以及用2台金厚度量測設備量測，此時要 以 SPC 管制圖管控的話，最少需要用幾張管制圖？",
    "question": "某家電路板廠有3條鍍金設備同時生產，以及用2台金厚度量測設備量測，此時要 以 SPC 管制圖管控的話，最少需要用幾張管制圖？",
    "options": [
      "可簡化合併為一張管制圖",
      "以3條生產線分別管控，使用3張管制圖",
      "需要用5張管制圖管理",
      "需要用 6 張管制圖管理"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】統計製程管制（SPC）有理子組與多設備管制圖劃分原則。\n【正確答案說明】(B) SPC 管制圖的基本假設是製程具備均質性（同質群體）。當工廠有 3 條獨立鍍金生產線時，各線的藥水濃度、陰極夾具、電流密度分佈及流場動態均有獨立差異，不可混合繪圖（否則會造成虛假變異）。因此必須「以 3 條生產線分別管控，使用 3 張管制圖」。量測設備雖有 2 台，但只要通過 MSA 評估確保一致性，量測值即反映各線實際水準。\n【選項辨析】\n- (A) 簡化合併為一張管制圖：會將不同設備間的機械性差異混入群內變異，導致管制圖失去偵測異常之能力。\n- (B) 以3條生產線分別管控，使用3張管制圖：正確。依獨立生產線進行分層獨立監控為標準 SPC 原則。\n- (C) 需要用5張管制圖管理：無此理論依據。\n- (D) 需要用6張管制圖管理：若是 3 條產線配 2 台量測機完全交叉也不必要，量測設備應以 MSA（Gage R&R）管控。",
