    "num": 10,
    "display_num": 10,
    "pdf_num": 10,
    "stem": "PTH 化學銅在孔壁的沉積覆蓋是否良好，通常是用下列何種方法來檢查？",
    "question": "PTH 化學銅在孔壁的沉積覆蓋是否良好，通常是用下列何種方法來檢查？",
    "options": [
      "以九孔鏡檢查孔壁",
      "以切片作背光檢查",
      "將切片抹氨水後以顯微鏡檢查",
      "對切片之孔壁以顯微鏡俯視檢查"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】PTH（化學鍍銅/通孔金屬化）孔壁覆蓋完整性之背光測試法。\n【正確答案說明】(B) PTH（Plated Through Hole）化學銅沉積僅約 20~40 μ-inch，肉眼或一般光學鏡難以直接穿透孔內看清是否微觀斷洞。品管標準方法是取試片製作微切片（Microsection）打磨至孔中心線，關閉正上方光源，改從試片後方進行背光穿透（Backlight Test），若孔壁透出光亮點即代表化學銅覆蓋不良或有空洞，並以 1~10 級進行評級。\n【選項辨析】\n- (A) 以九孔鏡檢查孔壁：九孔鏡用於外觀或較大孔徑之斜視觀察，無法精準評級化學銅超薄覆蓋性。\n- (B) 以切片作背光檢查：正確。背光測試（Backlight test）是國際標準認可評估沉銅覆蓋率之經典手法。\n- (C) 將切片抹氨水後以顯微鏡檢查：抹氨水不是檢測化學銅覆蓋率的常規方法。\n- (D) 對切片之孔壁以顯微鏡俯視檢查：俯視無法觀察垂直孔壁全斷面的連續背光遮蔽性。",
