    "pdf_num": 11,
    "stem": "鑽孔可以3片一疊同時鑽時，品管檢查是選取下列何片來檢查？",
    "question": "鑽孔可以3片一疊同時鑽時，品管檢查是選取下列何片來檢查？",
    "options": [
      "最上面一片",
      "中間的一片",
      "最下面一片",
      "輪流抽上中下的一片"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】PCB 機械鑽孔製程之疊板抽檢品質控制。\n【正確答案說明】(C) 機械鑽孔時疊合 3 片板材鑽孔，鑽針從最上片切入，鑽至最下片時鑽頭磨耗最大、排屑阻力最高、孔偏（Runout）與毛頭（Burr）及孔壁撕裂粗糙度最為嚴重。因此品管抽檢與首件檢驗時，必須選取品質條件最嚴苛的「最下面一片」來檢驗，只要最底片合格，其餘各層通常皆能符合標準。\n【選項辨析】\n- (A) 最上面一片：受蓋板保護且剛切入，毛頭與孔偏通常最小。\n- (B) 中間的一片：受力穩定，非最劣情境。\n- (C) 最下面一片：正確。最底層承受最大的鑽針偏轉應力與出刀毛頭，為最劣檢驗點（Worst case）。\n- (D) 輪流抽上中下的一片：常規檢驗首重最劣層（最底片）的完整合格性。",
    "source_id": "pcb-27f9abe1103ae6c8",
