    "stem": "PTH 化學銅在孔壁的沉積厚度，通常控制在下列何範圍？(單位：μ-inch)",
    "question": "PTH 化學銅在孔壁的沉積厚度，通常控制在下列何範圍？(單位：μ-inch)",
    "options": [
      "10-20",
      "20-40",
      "40-80",
      "80-120"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】化學銅（Electroless Copper / PTH）沉積厚度規格管制。\n【正確答案說明】(B) PTH 化學沉銅的主要功能是使絕緣孔壁導電化，以便後續進行全板電鍍或一次電鍍銅。沉積層太薄易氧化或電鍍吹孔，太厚則化學鍍沈積時間過長且藥水易自我分解。標準化學銅厚度範圍一般控制在「20～40 μ-inch」（約 0.5～1.0 μm）。\n【選項辨析】\n- (A) 10-20 μ-inch：厚度過薄，耐後續酸洗與微蝕裕度不足，容易造成孔破。\n- (B) 20-40 μ-inch：正確。一般常規化學沉銅標準製程控制厚度即為 20~40 μ-inch（約 0.5~1.0 微米）。\n- (C) 40-80 μ-inch：偏高，通常為特殊厚化學銅工藝。\n- (D) 80-120 μ-inch：過厚，化學沉銅沉積速率慢，成本過高且鍍液容易失控。",
    "source_id": "pcb-27f9abe1103ae6c8",
    "source_version": "official-115-01",
