    "stem": "下列何項最可能是造成電路板的阻焊漆(Solder Mask)附著力不良的原因？",
    "question": "下列何項最可能是造成電路板的阻焊漆(Solder Mask)附著力不良的原因？",
    "options": [
      "阻焊漆的前處理烘乾不足",
      "阻焊漆印刷時，有些參數設定不恰當",
      "阻焊漆的預烘段溫度太低",
      "阻焊漆的後烘段溫度太高或烘烤時間過長"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】防焊綠漆（Solder Mask）附著力不良與前處理乾燥控制。\n【正確答案說明】(A) 阻焊漆（Solder Mask）塗佈前，銅面須經過微蝕粗化與水洗清洗，若「前處理烘乾不足」，殘留微量水分在銅面微孔隙內，後續印刷阻焊漆並經熱烘烤時，水氣受熱急遽汽化膨脹，會破壞漆膜與銅界面的凡得瓦力與共價結合，導致阻焊漆起泡或附著力（百格測試）嚴重不良。\n【選項辨析】\n- (A) 阻焊漆的前處理烘乾不足：正確。殘留水氣在後續受熱時引發界面脫層剝離。\n- (B) 阻焊漆印刷時，有些參數設定不恰當：主要影響厚度均勻性、氣泡或搭墨，非銅面附著力最致命根因。\n- (C) 阻焊漆的預烘段溫度太低：預烘溫度偏低只會導致指觸乾燥不足或後續曝光黏底片，附著力主要由前處理與後烘交聯決定。\n- (D) 阻焊漆的後烘段溫度太高或烘烤時間過長：後烘充分通常有助於交聯硬化提高附著力，除非過度老化脆化。",
