    "pdf_num": 14,
    "stem": "線路製作流程中，乾膜曝光顯影後，要檢查乾膜與銅面交接處的顯影狀況。下列 何種檢查工具或設備最適合？",
    "question": "線路製作流程中，乾膜曝光顯影後，要檢查乾膜與銅面交接處的顯影狀況。下列 何種檢查工具或設備最適合？",
    "options": [
      "10-50倍放大鏡",
      "FIB 聚焦離子束顯微鏡",
      "切片以顯微鏡檢查",
      "SEM 掃描式電子顯微鏡"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】微細線路光阻顯影腳部（Footing）之高解析顯微觀測工具。\n【正確答案說明】(D) 乾膜曝光顯影後，欲檢視乾膜側壁垂直度以及乾膜底部與銅面交界處是否有殘膠或裙邊（Footing / Scum），尺寸皆在微米乃至次微米尺度，且需要深景深觀察立體形貌，最適合且解析力充足的設備為「SEM 掃描式電子顯微鏡（Scanning Electron Microscope）」。\n【選項辨析】\n- (A) 10-50倍放大鏡：放大倍率遠遠不足，無法觀察乾膜微米級的交界底部顯影狀況。\n- (B) FIB 聚焦離子束顯微鏡：通常用於奈米級切割與微區斷面分析，成本極高且破壞樣品，不適合作為日常乾膜顯影外觀觀察工具。\n- (C) 切片以顯微鏡檢查：一般光學切片製作費時且研磨容易拉扯乾膜邊緣造成失真。\n- (D) SEM 掃描式電子顯微鏡：正確。具有超高放大倍率與強大景深，是評估光阻側壁垂直度與底部顯影殘膠的最佳標準工具。",
