    "stem": "化鎳浸金(ENIG)電路板中，鎳的厚度通常是在下列何範圍？(單位：μ-inch)",
    "question": "化鎳浸金(ENIG)電路板中，鎳的厚度通常是在下列何範圍？(單位：μ-inch)",
    "options": [
      "2-5",
      "20-60",
      "80-200",
      "200-400"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】化鎳浸金（ENIG）表面處理中鎳層規格厚度。\n【正確答案說明】(C) 在 ENIG（Electroless Nickel Immersion Gold）表面處理中，鎳層作為銅與焊錫之間的阻障層（Diffusion Barrier）並提供平整表面，其化學鍍鎳厚度規範（如 IPC-4552）通常為「80～200 μ-inch」（約 2.0～5.0 μm，常用標稱約 120~150 μ-inch）；而外層浸金則僅約 1.2～3.0 μ-inch。\n【選項辨析】\n- (A) 2-5 μ-inch：此為外層浸金（Immersion Gold）的厚度範圍，非鎳層。\n- (B) 20-60 μ-inch：鎳層厚度過薄，無法有效阻擋銅錫原子相互熱擴散，易導致焊接界面老化劣化。\n- (C) 80-200 μ-inch：正確。IPC-4552 規範之 ENIG 鎳層厚度標準通常落在 80~200 μ-inch（或約 3~5 μm）。\n- (D) 200-400 μ-inch：偏厚，過厚的鎳層內應力大且增加電鍍成本與脆裂風險。",
