    "stem": "有關對電路板要求的文件中，當規格要求不一樣時，下列何者文件為最優先考 慮？",
    "question": "有關對電路板要求的文件中，當規格要求不一樣時，下列何者文件為最優先考 慮？",
    "options": [
      "IPC 國際規範",
      "客戶的通用規格書(Specification)",
      "客戶的藍圖",
      "客戶的訂單"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】品質契約與技術文件之優先適用位階法則。\n【正確答案說明】(D) 依據國際商業契約與 IPC 規範共通原則，當各項文件規格有衝突時，其效力優先順序為：「採購合約/訂單（Purchase Order / Contract）」>「特定客戶藍圖（Drawing）」>「客戶特定規格書（Customer Specification）」>「業界通用國際規範（如 IPC 系列）」。因此以「客戶的訂單」為最優先考慮。\n【選項辨析】\n- (A) IPC 國際規範：屬於通用基礎標準，在合約或藍圖無特殊指明時作為基準，位階最低。\n- (B) 客戶的通用規格書：位階低於單獨訂單與專屬圖面。\n- (C) 客戶的藍圖：具備高優先級，但若訂單條款中有明文修訂或特殊商業例外指定，仍以訂單（Purchase Order）之法律與履約約束力為最高。\n- (D) 客戶的訂單：正確。訂單是雙方當下成立買賣契約的最終意志體現，具備最優先適用地位。",
