    "stem": "QC Story 的應用在選定不良項目後，要評估、掌握不良問題主要的發生原因，用 下列何種圖表最適合？",
    "question": "QC Story 的應用在選定不良項目後，要評估、掌握不良問題主要的發生原因，用 下列何種圖表最適合？",
    "options": [
      "魚骨圖",
      "直方圖",
      "散佈圖",
      "柏拉圖"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】QC Story 改善歷程中掌握問題主因之核心手法。\n【正確答案說明】(D) 在 QC Story（品管圈改善歷程）中，當選定主要不良主題之後，欲評估各類不良現象的發生頻率與嚴重性，掌握問題的關鍵少數（抓出佔 80% 的主要不良原因），最標準合適的圖表為「柏拉圖」。\n【選項辨析】\n- (A) 魚骨圖：用於在掌握不良現象後，進一步推導其背後的要因與真因。\n- (B) 直方圖：用於評估連續數據的常態分佈分佈廣度與偏態。\n- (C) 散佈圖：用於驗證兩個連續變數之間的相關性。\n- (D) 柏拉圖：正確。依 80/20 法則評估並聚焦最主要的損失或不良項目。",
    "source_id": "pcb-27f9abe1103ae6c8",
    "source_version": "official-115-01",
    "question_uid": "pcb-d9af4961ca0fbd6753b4fff3",
    "content_hash": "2683734a5339af155ebe2fb9baa07b433f6acd4b3afb04627705b00e1e934e75",
