    "stem": "要瞭解數據分佈情形，看是有集中趨勢或雜散分散，應該用下列何種圖表？",
    "question": "要瞭解數據分佈情形，看是有集中趨勢或雜散分散，應該用下列何種圖表？",
    "options": [
      "散佈圖",
      "直方圖",
      "檢查表",
      "層別圖"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】直方圖（Histogram）對計量數據分佈型態之觀測功能。\n【正確答案說明】(B) 直方圖（Histogram）將連續型計量數據（如銅厚、線寬、孔徑）分成若干組區間，以長條柱高展示各區間數據頻率，能一目瞭然地看出數據的「集中趨勢（平均值位置）」與「雜散離散程度（標準差/分佈寬度）」以及是否有雙峰或偏態。\n【選項辨析】\n- (A) 散佈圖：用於呈現兩組變數之間的相依相關關係。\n- (B) 直方圖：正確。為觀察數據分配形態、集中趨勢與離散分散的最佳圖表。\n- (C) 檢查表：用於現場數據的搜集與記錄，非圖形化分配呈現工具。\n- (D) 層別圖：將數據分類切割，不單獨直接表現頻率分佈形狀。",
