    "num": 21,
    "display_num": 21,
    "pdf_num": 21,
    "stem": "品管抽樣計劃常引用 ANSI/ASQC Z1.4 (原 MIL-STD-105 E)抽樣表及允收品質水準 (AQL)，下列何項對此抽樣計劃的敘述有誤？",
    "question": "品管抽樣計劃常引用 ANSI/ASQC Z1.4 (原 MIL-STD-105 E)抽樣表及允收品質水準 (AQL)，下列何項對此抽樣計劃的敘述有誤？",
    "options": [
      "AQL 的數值越高，允許的不良數越少",
      "一般檢驗水準分為Ⅰ級、Ⅱ級、Ⅲ級，Ⅰ級的抽樣數比Ⅱ級的抽樣數少",
      "產品的嚴重缺點、主要缺點、次要缺點的 AQL 值，應該分別訂定",
      "生產者風險率是指因為抽樣的關係，合格批被拒收的機率"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】計數值抽樣檢驗計畫 ANSI/ASQC Z1.4（MIL-STD-105E）之 AQL 觀念。\n【正確答案說明】(A) AQL（Acceptable Quality Level，允收品質水準）代表買賣雙方可接受的製程平均不良率上限。AQL 數值越大，代表對品質要求越寬鬆，因此「允許的不良數越多」而非越少；AQL 數值越小，才代表要求越嚴格、允許的不良品數越少。故 (A) 敘述有誤。\n【選項辨析】\n- (A) AQL 的數值越高，允許的不良數越少：錯誤（正確答案）。AQL 值越高代表要求越寬鬆，允許的不良數越多。\n- (B) 一般檢驗水準分為Ⅰ級、Ⅱ級、Ⅲ級，Ⅰ級抽樣數比Ⅱ級少：敘述正確（Ⅰ級為減量，Ⅱ級為正常，Ⅲ級為加嚴）。\n- (C) 產品的嚴重缺點、主要缺點、次要缺點的 AQL 值應該分別訂定：敘述正確（嚴重缺點 AQL 最嚴，如 0 或 0.1；次要缺點可放寬至 2.5 或 4.0）。\n- (D) 生產者風險率是指合格批因抽樣而被誤判拒收的機率（α風險）：敘述正確。",
