    "explanation": "【核心考點】計數抽樣計畫 ANSI/ASQC Z1.4 的標準組成要素。\n【正確答案說明】(C) ANSI/ASQC Z1.4 抽樣標準表格主要規定了：批量大小與檢驗水準（檢驗數量代字）、抽樣數（檢驗數量）、允收/拒收判定數（Ac / Re，允許不合格數量）以及正常/加嚴/減量轉移規則。至於具體的「檢驗方法」（如光學顯微鏡觀察、四點探針量測、切片製作方法等），屬於技術檢驗作業規範，並非抽樣表本身所定義之內容。\n【選項辨析】\n- (A) 檢驗數量：抽樣表依批量與水準直接規定樣本大小（Sample Size）。\n- (B) 檢驗水準：抽樣標準內明定特殊水準 S1-S4 與一般水準 I, II, III。\n- (C) 檢驗方法：正確（不包含在抽樣計畫標準範圍內）。\n- (D) 允許不合格的數量：抽樣表內明定允收數 Ac 與拒收數 Re。",
