    "stem": "統計製程管制 SPC 的理論基礎是基於機率的呈現是下列何種分配？",
    "question": "統計製程管制 SPC 的理論基礎是基於機率的呈現是下列何種分配？",
    "options": [
      "常態分配",
      "動態分配",
      "靜態分配",
      "穩態分配"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】統計製程管制（SPC）之統計學理論基礎。\n【正確答案說明】(A) 統計製程管制圖（如 X-bar - R 圖）係以機率論中的「常態分配（Normal Distribution, 高斯分配）」與「中央極限定理（Central Limit Theorem）」為數學基石，利用平均值 ± 3 個標準差（±3σ）作為天然變異管制界限。\n【選項辨析】\n- (A) 常態分配：正確。SPC 管制界限公式與製程能力指標（Cp/Cpk）均建立在數據服從常態分配之假設上。\n- (B) 動態分配：非統計學標準機率分配名詞。\n- (C) 靜態分配：非統計學標準機率分配名詞。\n- (D) 穩態分配：非機率論基礎分配名詞。",
    "source_id": "pcb-27f9abe1103ae6c8",
    "source_version": "official-115-01",
    "question_uid": "pcb-152c1d13cb74cd3bd2022c17",
