    "pdf_num": 24,
    "stem": "當 SPC 管制圖出現異常，但一時找不出異常原因，其屬於下列何種情形？",
    "question": "當 SPC 管制圖出現異常，但一時找不出異常原因，其屬於下列何種情形？",
    "options": [
      "可歸屬原因",
      "機遇原因",
      "一般原因",
      "機率因素"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】SPC 製程變異分類：機遇原因與可歸屬（特殊）原因。\n【正確答案說明】(A) SPC 理論將變異分為兩類：(1) 機遇原因（Common Cause / Chance Cause）：製程本身固有的微小雜訊變異；(2) 可歸屬原因（Assignable Cause / Special Cause）：外部異常干擾（如人員操作失誤、原材料批次突變、設備破裂等）。當管制圖發出超出管制界限或出現趨勢等異常警報時，代表製程受到了特定「可歸屬原因（特殊原因）」的影響，即便現場暫時未查明，其本質仍屬可歸屬原因，必須持續追查直至排除。\n【選項辨析】\n- (A) 可歸屬原因：正確。管制圖出現統計異常點必然意味著存在可歸屬的特殊原因。\n- (B) 機遇原因：機遇原因引起的變異永遠在 ±3σ 管制界限內隨機跳動，不會造成判定異常。\n- (C) 一般原因：同機遇原因。\n- (D) 機率因素：機遇原因之同義泛稱。",
