    "stem": "品管 8D 手法是很嚴謹、能找出產品不良的原因及徹底防止再發生不良的好工 具，有關對8D 的理解，下列何者有誤？",
    "question": "品管 8D 手法是很嚴謹、能找出產品不良的原因及徹底防止再發生不良的好工 具，有關對8D 的理解，下列何者有誤？",
