    "explanation": "【核心考點】品管 8D 問題解決程序之適用範圍與資源配置原則。\n【正確答案說明】(C) 8D（Eight Disciplines）是高度系統化且極耗費跨部門工時與資源的嚴謹解決工具，主要應用於「重大品質異常、反覆發生的慢性難題、客戶重大投訴或嚴重安全問題」。若一般日常已知或簡單之微小品質問題亦全面盲目使用 8D，將導致組織資源耗竭且行政流程冗長。因此「盡可能都用 8D」是錯誤的管理認知。\n【選項辨析】\n- (A) 8D 成員是跨部門團隊：敘述正確（D1 要求建立具備多元專業之團隊）。\n- (B) 臨時防堵措施需隔離已產出不良品：敘述正確（D3 圍堵行動防止不良流向下一製程或客戶）。\n- (C) 遇有品質問題盡可能都用8D：錯誤（正確答案）。8D 應視問題嚴重度與複雜性擇要發動。\n- (D) 預防再發措施包含修改 SOP 與教育訓練：敘述正確（D7 預防再發與標準化程序）。",
