    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】SPC 管制圖 Western Electric 八大判異規則（超出 3σ）。\n【正確答案說明】(C) 在 SPC 管制圖的標準判異原則中，「任何單一點超出 3 倍標準差管制界限（UCL 或 LCL）之外」，代表發生此機率在正常狀態下僅為 0.27%，可立即判定為製程發生異常。\n【選項辨析】\n- (A) 有任一點超出1倍標準差之外：常態下約有 31.7% 點會落在 1σ 外，屬於常規跳動。\n- (B) 有任一點超出2倍標準差之外：常態下約有 4.5% 點會落在 2σ 外，單一點落於 2σ 外不可單獨判定異常（需連續 3 點中有 2 點才算 Zone A 警訊）。\n- (C) 有任一點超出3倍標準差管制界線之外：正確。為管制圖判定異常最基本、最重要的第一法則。\n- (D) 有連續 5 點出現在中心線同一側：標準判異規則要求「連續 8 點或 9 點在中心線同一側」方可判定製程中心漂移。",
    "source_id": "pcb-27f9abe1103ae6c8",
    "source_version": "official-115-01",
    "question_uid": "pcb-76e8b0cae2cf02f4ff98c309",
    "content_hash": "042a54b9af7eb5c6d5d081b9820095fe4550fa7a8415e50fd1d24e15e0d5db10",
