    "explanation": "【核心考點】成型製程（CNC Routing / 沖切）首件確認防錯管制。\n【正確答案說明】(D) 成型作業（Routing / 銑切外型）直接決定成品板之外觀尺寸、板邊公差、導角、V-Cut 對位與槽孔位置。若程式版本錯誤、補償半徑（Tool Compensation）設錯或銑刀安裝偏斜，整批板子將全數報廢無法重工。因此每日開線量產前，必須先製作 1~4 片首件，經二次元光學測量儀全尺寸檢驗合格後方能全面量產。\n【選項辨析】\n- (A) 壓合作業：壓合為大批量疊板熱壓，不可能單獨壓 1~2 片做事前首件。\n- (B) 二次銅電鍍作業：為連續飛巴槽液鍍銅，以 Dummy 板拉鍍或隨板試片監控，非單片放行量產。\n- (C) PTH 化學銅作業：為大槽批次化學沉積反應，不採單片試做方式。\n- (D) 成型作業：正確。外型加工尺寸公差極嚴格且程式具易變性，各廠開線均嚴格執行首件首片量測判定制度。",
