    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】ANSI/ASQC Z1.4 抽樣計畫生產者風險與檢測誤差概念辨析。\n【正確答案說明】(B) 生產者風險率（α 風險）在統計抽樣學上嚴格定義為：「品質達到或優於 AQL 的合格批，僅僅純粹因為『隨機抽樣抽到較多不良品之機率性偏差』而被錯誤拒收的機率」。檢測儀器不準確或量測系統誤差屬於 MSA（量測系統分析）中的系統偏差或人為失誤，並不包含在統計抽樣表所界定的理論生產者風險率之內。故 (B) 敘述錯誤。\n【選項辨析】\n- (A) 嚴重、主要、次要缺點 AQL 分別訂定：敘述正確。\n- (B) 生產者風險率包含檢測儀器不準確造成的：錯誤（正確答案）。生產者風險純指抽樣機率波動導致的誤判拒收，不含儀器量測失真。\n- (C) 正常檢驗連續 10 批合格可轉為減量檢驗（Ⅰ級水準）：敘述符合轉移通則概念。\n- (D) 檢驗費時或破壞性檢測應採用特殊抽樣水準 S1-S4：敘述正確（特殊水準樣本數小以降低破壞成本）。",
