    "stem": "統計製程管制(SPC)是一種能即時監控生產流程的品質管理方法，有關 SPC 的敘述 下列何者有誤？",
    "question": "統計製程管制(SPC)是一種能即時監控生產流程的品質管理方法，有關 SPC 的敘述 下列何者有誤？",
    "options": [
      "SPC 的應用，首先是要篩選出製程當中哪些是重要項，且該項適合以 SPC 做即 時監控的，才用 SPC 管理",
      "管制圖是 SPC 的核心工具，用於監控製程是否處於穩定狀態",
      "SPC 僅適用於可量化的場域，不適用於無法量化的場域",
      "SPC 只適用對產品的品質管控，不適用於對生產設備狀況的管控"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】統計製程管制（SPC）在設備參數監控之延伸應用。\n【正確答案說明】(D) SPC 不僅能應用於產品品質特性（如銅厚、線寬、孔徑），亦廣泛應用於關鍵生產設備狀態與製程參數之線上監控（例如電鍍槽溫度、噴壓、微蝕咬蝕速率、化驗分析濃度、回焊爐溫等）。宣稱「只適用對產品品質管控，不適用於設備狀況管控」是完全錯誤的觀念。\n【選項辨析】\n- (A) SPC 應用首先要篩選關鍵重要且具監控意義的項目：敘述正確。\n- (B) 管制圖是監控製程是否處於統計穩定狀態之核心工具：敘述正確。\n- (C) SPC 僅適用於可量化之場域：敘述正確（計量型或計數型皆需量化計數）。\n- (D) SPC 只適用對產品的品質管控，不適用於對生產設備狀況的管控：錯誤（正確答案）。現代智慧製造普遍將 SPC 運用於設備參數監控。",
