    "stem": "電路板上的防焊漆(Solder Resister)主要有下列哪些功用？",
    "question": "電路板上的防焊漆(Solder Resister)主要有下列哪些功用？",
    "options": [
      "防止電路板組裝時密集焊接點短路",
      "幫助電路板散熱",
      "避免清洗組裝後的電路板吸水受潮",
      "保護線路，防止線路氧化及刮傷"
    ],
