    "ans_text": "標準答案：(AD)",
    "is_multiple": true,
    "explanation": "【核心考點】阻焊漆（Solder Resister / Solder Mask）之主要功用。\n【正確答案說明】(AD)\n- (A) 防止焊接短路：在波焊（Wave Soldering）或迴焊（Reflow）組裝時，阻焊漆覆蓋非銲接線路，防止密集錫墊間產生錫橋短路（Solder Bridging）。\n- (D) 保護線路防止氧化與刮傷：阻焊漆形成堅韌絕緣交聯保護層，隔絕大氣濕氣使銅線不氧化，並抵抗後續組裝碰觸刮傷。\n防焊漆為高分子聚合物，熱傳導率極低，無法提供顯著散熱效果（(B)錯誤）；組裝清洗主要是去除助焊劑殘留，防焊漆目的並非避免清洗吸水（(C)錯誤）。故正確答案為 AD。\n【選項辨析】\n- (A) 正確：防止 SMT 組裝焊點短路搭錫。\n- (B) 錯誤：高分子漆熱阻高，無散熱功能。\n- (C) 錯誤：非阻焊漆之主設計機能。\n- (D) 正確：提供長效絕緣、抗氧化及防刮機械保護。",
