    "question": "有關電路板防焊漆作業流程，下列哪幾項會造成阻焊漆顯影不完全？",
    "options": [
      "阻焊漆顯影機的噴嘴堵塞",
      "阻焊漆顯影後的烘烤(Post Curing)溫度太高",
      "阻焊漆太厚",
      "碳酸鈉顯影液的溫度太低"
    ],
