    "ans_text": "標準答案：(ACD)",
    "is_multiple": true,
    "explanation": "【核心考點】阻焊漆顯影不完全（Scum / 残膠）之製程成因。\n【正確答案說明】(ACD)\n- (A) 顯影機噴嘴堵塞：噴壓下降、流量不均，藥水無法有效沖刷溶解未曝光區綠漆，造成顯影殘留（正確）。\n- (B) 後烘烤（Post Curing）溫度太高：後烘烤是在顯影「完成後」進行的熱交聯硬化程序，不可能反過來影響先前的顯影不完全（錯誤）。\n- (C) 阻焊漆太厚：綠漆過厚導致顯影液難以在有限傳輸時間內穿透溶解至底部銅面（正確）。\n- (D) 碳酸鈉顯影液溫度太低：碳酸鈉藥水活性與化學溶解速率隨溫度下降而急劇降低，導致顯影不足（正確）。\n故造成顯影不完全的原因為 ACD。\n【選項辨析】\n- (A) 正確：噴嘴堵塞引發沖洗盲區。\n- (B) 錯誤：後烘烤在顯影之後，時序不符。\n- (C) 正確：膜厚過厚增加溶解阻抗。\n- (D) 正確：溫度過低顯影反應速率不足。",
