    "is_multiple": true,
    "explanation": "【核心考點】SPC 管制界限與公差規格界限之本質區別及適用範疇。\n【正確答案說明】(AD)\n- (A) 敘述有誤：SPC 管制圖的中心線（CL）與管制上下限（UCL / LCL）完全是由「製程實際收集之數據計算平均值 ± 3 個標準差（3σ）」決定，絕對不是以客戶的規格上限與下限（USL / LSL）設定！將管制界限混同於規格界限是嚴重的觀念錯誤。\n- (D) 敘述有誤：SPC（統計製程管制）的核心精神是「在製造過程中即時預防異常」，而 OQC（出貨檢驗）是最後階段的成品允收檢驗（通常採用抽樣檢驗計畫如 AQL 查驗），不使用 SPC 進行製程動態控制。\n(B) 與 (C) 皆為標準正確觀念。故題目問哪些有誤，答案為 AD。\n【選項辨析】\n- (A) 錯誤敘述（符合題意）：SPC 管制限由製程固有變異決定，非規格限。\n- (B) 正確敘述：製作管制圖需計算平均值、標準差與管制限。\n- (C) 正確敘述：落在 3σ 外即判定異常。\n- (D) 錯誤敘述（符合題意）：SPC 為製程中管制工具，OQC 採用驗收抽樣計畫。",
