    "ans_text": "標準答案：(ACD)",
    "is_multiple": true,
    "explanation": "【核心考點】內層線路製作造成線路斷路（Open circuit）之主要原因。\n【正確答案說明】(ACD) 內層負片法線路形成中，任何造成銅面凹陷或乾膜過早脫落/遮光未硬化的缺陷，都會導致蝕刻液咬穿線路造成斷路：\n- (A) 銅面有針孔凹陷：銅層原始厚度不足，蝕刻後凹陷處直接被咬穿導致「斷路」（正確）。\n- (C) 乾膜與銅面間有空氣泡：乾膜無法黏著於銅面，顯影時乾膜泡破脫落，蝕刻液滲入將線路蝕穿造成「斷路」（正確）。\n- (D) 曝光時底片有髒點：髒點遮擋 UV 光，導致乾膜未能交聯光聚合，顯影後被洗掉，蝕刻後線路形成「斷路」（正確）。\n(B) 曝光吸真空不良會引起繞射殘膠造成短路。故造成斷路之選項為 ACD。\n【選項辨析】\n- (A) 正確：銅箔針孔極易經蝕刻演變為斷路。\n- (B) 錯誤：吸真空不良光線折射殘留多造成短路。\n- (C) 正確：膜下氣泡導致光阻脫落遭受蝕刻形成缺口斷路。\n- (D) 正確：底片髒點遮光導致光阻未硬化遭蝕除形成斷路。",
