    "explanation": "【核心考點】PCB 各製程潔淨度等級與無塵室（Cleanroom）環境需求。\n【正確答案說明】(BC)\n- (B) 壓合前的疊板（Lay-up）：疊板時若有毛屑、粉塵或纖維掉入膠片與內層銅箔之間，熱壓後會產生凹痕、空洞或介質耐壓絕緣崩潰，因此疊板區必須在無塵室（通常 Class 10,000 或更高）環境作業。\n- (C) 線路製作（黃光區 / 乾膜壓膜、曝光）：微細線路（L/S < 50 μm）對落塵極度敏感，一顆數微米的微塵即會導致斷路或短路，必須在 Class 100 ~ 1,000 級黃光無塵室內作業。\n鑽孔會產生大量玻璃纖維粉屑，屬於機械加工粉塵區（(A)錯誤）；OSP 表面處理為化學水平濕製程線，只需排風與常規廠房環境（(D)錯誤）。故答案為 BC。\n【選項辨析】\n- (A) 鑽孔：產生大量切屑粉塵，非無塵室。\n- (B) 壓合前的疊板：正確。嚴防粉塵夾雜造成層間凹洞短路。\n- (C) 線路製作：正確。黃光顯影曝光核心無塵管制區。\n- (D) OSP 表面處理：為濕式化學清洗槽，非無塵室。",
