    "pdf_num": 10,
    "stem": "以二次銅法製作2.5mm 板厚的電路板，下列哪些項有可能是0.25 mm 孔徑導通孔 孔破的原因？",
    "question": "以二次銅法製作2.5mm 板厚的電路板，下列哪些項有可能是0.25 mm 孔徑導通孔 孔破的原因？",
    "options": [
      "線路製作時，壓乾膜不恰當",
      "線路製作時，曝光不恰當",
      "鍍二次銅時，空氣泡卡在導通孔內",
      "線路蝕刻時，噴嘴壓力過大"
    ],
    "answer": "AC",
    "ans_text": "標準答案：(AC)",
    "is_multiple": true,
    "explanation": "【核心考點】高厚徑比（Aspect Ratio）導通孔二次銅孔破（Void）之根因分析。\n【正確答案說明】(AC) 2.5 mm 板厚、0.25 mm 孔徑的厚徑比高達 10:1：\n- (A) 線路壓乾膜不恰當：圖案電鍍（二次銅法）時需以乾膜做為電鍍抗鍍阻劑，若壓膜貼附不良或孔口乾膜破孔滲入，會干擾孔內導電均勻度；或者孔口乾膜蓋孔撕裂碎屑掉入深孔內阻礙電鍍，導致孔壁無銅破孔（正確）。\n- (C) 鍍二次銅時空氣泡卡在導通孔內：在 10:1 的高縱橫比深孔中，若電鍍槽搖擺、噴流或孔內潤濕不足，微氣泡極易困在深孔中央形成遮蔽，阻斷鍍液離子傳輸，造成孔壁局部完全無法鍍上銅層而產生嚴重的吹孔或孔破（Void）（正確）。\n曝光能量不當主要影響乾膜顯影線寬而非深孔孔壁（(B)不符）；蝕刻噴壓影響外層線路側蝕，孔內已有錫保護或貫通（(D)不符）。故答案為 AC。\n【選項辨析】\n- (A) 正確：壓膜異常殘渣落入或孔口微破裂導致孔內鍍層阻斷孔破。\n- (B) 錯誤：曝光主要影響乾膜解析度。\n- (C) 正確：高厚徑比深孔極易被微氣泡堵塞形成盲區孔破。\n- (D) 錯誤：二次銅法蝕刻時孔壁受抗蝕錫層保護，非孔破主因。",
