    "num": 1,
    "display_num": 1,
    "pdf_num": 1,
    "stem": "硬質印刷電路板(硬板)常見的銅皮為電解(ED)銅皮，軟板也有使用電解(ED)銅皮， 但與軟板常用之壓延(RA 或 HA)銅皮製作方法與特性有所不同。下列何者不是電 解銅皮的特性？",
    "question": "硬質印刷電路板(硬板)常見的銅皮為電解(ED)銅皮，軟板也有使用電解(ED)銅皮， 但與軟板常用之壓延(RA 或 HA)銅皮製作方法與特性有所不同。下列何者不是電 解銅皮的特性？",
    "options": [
      "常溫晶粒型態為上下柱狀結晶",
      "適用於低撓曲組裝",
      "價格較壓延銅皮低",
      "適用於複雜彎折與撓曲的組裝方式"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】電解銅皮（ED）與壓延銅皮（RA）之微觀晶粒結構與撓曲特性。\n【正確答案說明】(D) 電解銅皮（Electrodeposited Copper, ED）是在硫酸銅鍍液中透過陰極滾輪電沉積生成，其微觀結晶呈垂直柱狀（Columnar structure）。柱狀晶在承受劇烈重複彎折時，柱狀晶界極易開裂導致斷裂，因此僅適用於「低撓曲（Static / Flex-to-install）」組裝，而不適用於「動態重複彎折或複雜撓曲的組裝方式（Dynamic Flexing）」。後者必須採用經高溫退火、具水平層狀晶粒結構之壓延退火銅箔（RA / HA 銅皮）。故 (D) 不是電解銅皮的特性。\n【選項辨析】\n- (A) 常溫晶粒型態為上下柱狀結晶：敘述正確（ED 銅特徵為垂直基板生長的柱狀晶）。\n- (B) 適用於低撓曲組裝：敘述正確（適合靜態組裝折彎一次後固定使用）。\n- (C) 價格較壓延銅皮低：敘述正確（ED 銅連續沉積製造成本低於多道精密冷軋退火之 RA 銅）。\n- (D) 適用於複雜彎折與撓曲的組裝方式：錯誤（正確答案）。動態頻繁彎折必須採用壓延退火銅箔（RA/HA）。",
