    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】軟性電路板功能性檢測項目範疇。\n【正確答案說明】(A) 軟板檢驗分為「功能性檢測（Functional Testing）」與「外觀檢驗（Visual Inspection）」。「外觀顏色」（如覆蓋膜黃色深淺、油墨色差）屬於外觀或美觀檢驗項目，非產品的電氣或物理功能；而電氣特性（導通/阻抗/耐壓）、耐熱特性（熱應力、耐焊性）與可靠度（MIT 彎折次數、耐折性）均為不可或缺的核心功能檢測項目。故 (A) 不是主要功能檢測項目。\n【選項辨析】\n- (A) 外觀顏色：正確答案（屬於外觀目視檢查，非功能測試）。\n- (B) 電氣特性：核心功能（絕緣電阻、導通電阻、信號傳輸）。\n- (C) 耐熱特性：核心功能（耐浮焊、無鉛高溫迴焊測試）。\n- (D) 可靠度：核心功能（動態彎折壽命、溫濕度偏壓測試）。",
