    "explanation": "【核心考點】印刷電路板常用公英制單位精準換算。\n【正確答案說明】(C)\n- 1 inch（英吋）= 25.4 mm = 25400 μm = 1000 mil；\n- 1 mil = 1 / 1000 inch = 0.001 inch = 25.4 μm；\n- 1 μ-inch（微英吋）= 1 / 1,000,000 inch = 0.001 mil = 0.0254 μm；\n- 反算：1 mil =「1000 μ-inch」，而不是 100 μ-inch！故 (C) 換算錯誤。\n【選項辨析】\n- (A) 1 mil = 25.4μm：完全正確。\n- (B) 1μm = 39.37μ-inch：完全正確（1/0.0254 ≈ 39.37）。\n- (C) 1 mil = 100μ-inch：錯誤（正確答案，應為 1 mil = 1000 μ-inch）。\n- (D) 1000 mil = 1 inch：完全正確。",
