    "stem": "相比硬板的特性，下列何項不是軟板的優點？",
    "question": "相比硬板的特性，下列何項不是軟板的優點？",
    "options": [
      "有效的空間應用",
      "板材強度高且具備機械支撐性能",
      "可撓取",
      "輕薄短小"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】軟性電路板（FPC）與剛性電路板（Rigid PCB）之物性對比。\n【正確答案說明】(B) 軟板基材是以薄型聚醯亞胺（PI）膜構成，厚度極薄且質地柔軟易彎曲，其本身「剛性與機械支撐性能低」，若需承載較重的接插件或按鍵元件時，通常必須額外局部貼合「補強板（Stiffener，如 FR-4 或不鏽鋼片）」來提供支撐。「板材強度高且具備機械支撐性能」是硬板（剛性板）的典型特徵與優勢，而非軟板的優點。故選 B。\n【選項辨析】\n- (A) 有效的空間應用：軟板可立體折疊，大幅節省組裝內部機構空間。\n- (B) 板材強度高且具備機械支撐性能：錯誤（正確答案，屬於硬板優點，軟板本身剛性不足）。\n- (C) 可撓曲：軟板核心本質。\n- (D) 輕薄短小：厚度可小於 0.1 mm，重量極輕。",
    "source_id": "pcb-7d782d02ff054a5d",
