    "question": "下列何者不是覆蓋膜(Coverlay)的主要功能？",
    "options": [
      "導體間的絕緣",
      "防止銅面在迴焊或波焊製程中接觸到焊錫",
      "保護線路增加抗彎折能力",
      "光學反光特性"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】軟板覆蓋膜（Coverlay）之四大核心機能。\n【正確答案說明】(D) 軟板覆蓋膜（Coverlay, 聚醯亞胺膜搭配環氧膠層）的主要功能為：\n1. 保護微細銅線，防止大氣氧化與機械擦傷；\n2. 作為外層導體線路間的絕緣層（代替硬板的防焊綠漆）；\n3. 增加整體軟板耐彎折抗疲勞性能；\n4. 組裝銲接（迴焊/波焊）時遮蔽特定非焊接銅區以防沾錫短路。\n覆蓋膜並非光學元件，其功能中「不包含光學反光特性」。故 (D) 不是主要功能。\n【選項辨析】\n- (A) 導體間的絕緣：覆蓋膜基本電氣機能。\n- (B) 防止銅面焊接沾錫：組裝遮蔽焊錫之標準功能。\n- (C) 保護線路增加抗彎折能力：覆蓋膜對稱包覆中性軸，能大幅強化耐曲折壽命。\n- (D) 光學反光特性：錯誤（正確答案，非覆蓋膜之設計功能）。",
    "source_id": "pcb-7d782d02ff054a5d",
