    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】軟板與硬板防焊油墨（Solder Mask）耐撓曲配方差異。\n【正確答案說明】(C) 硬板所使用的液態感光防焊油墨（LPI / PSR），其樹脂系統在熱硬化後交聯密度極高，具有極高的硬度與抗劃傷性，但質地較脆；若直接使用於軟板上，軟板在彎折或撓曲時，硬板油墨會因無法承受形變應變而立即發生「龜裂（Cracking）、粉化或剝離脫落」。因此軟板專用防焊油墨必須添加特殊彈性體與低內應力改性樹脂，具有高耐撓折性，兩者「絕不可混用相同型號」。故 (C) 敘述有誤。\n【選項辨析】\n- (A) 兩者都可搭配電鍍 ED 銅箔：敘述正確（軟板無重複彎折區域可使用高延展 ED 銅）。\n- (B) 軟板常因彎折需求使用壓延銅，硬板不需要：敘述正確。\n- (C) 軟板防焊油墨可採用硬板型號：錯誤（正確答案）。硬板油墨耐彎折性差，彎折必龜裂。\n- (D) 使用不同成份絕緣基材：敘述正確（軟板為 PI/PET，硬板為環氧/玻纖布 FR-4）。",
