    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】軟板補強用不鏽鋼板（SUS）材料之磁性物理性質。\n【正確答案說明】(C)\n- 沃斯田鐵系不鏽鋼（如 SUS 301、SUS 304、SUS 316）：在退火狀態下通常為非磁性（無磁吸性或僅冷加工後微磁）；\n- 肥粒鐵系不鏽鋼（如 SUS 430）：內部組織為體心立方結構，具有顯著的「鐵磁性（具有磁吸功能）」。\n在某些精密電子產品機構定位或磁吸式組裝定位需求中，常特別指定使用具磁吸性之 SUS 430 鋼片補強板。故選 C。\n【選項辨析】\n- (A) SUS301：沃斯田鐵系，高強度彈簧鋼，基底無磁或弱磁。\n- (B) SUS304：標準沃斯田鐵系（18-8 不鏽鋼），常態無磁性。\n- (C) SUS430：正確。為肥粒鐵系不鏽鋼，具有優良磁吸導磁功能。\n- (D) SUS316：沃斯田鐵系（加鉬耐腐蝕），無磁性。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-c5bef7fbcb2f56ee19090e4e",
    "content_hash": "728e661b74327921e42673d1feef7e344cd808400150281c8b21a1e6b6c3cda1",
