    "stem": "有關減層蝕刻法的線寬管控，下列何者不是影響線路寬度的主要因素？",
    "question": "有關減層蝕刻法的線寬管控，下列何者不是影響線路寬度的主要因素？",
    "options": [
      "無塵室的落塵管理",
      "蝕刻因子(Etching Factor)管控",
      "曝光能量管控",
      "面銅銅厚的均勻性管控"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】減除法蝕刻（Subtractive Etching）線寬影響參數。\n【正確答案說明】(A) 減除法線寬的直接物理控制因素包括：面銅底銅厚度均勻性（影響咬蝕穿透時間）、曝光能量與聚焦（決定乾膜線寬尺寸）、顯影沖刷品質以及蝕刻機噴壓/蝕刻因子（決定側蝕量）。而「無塵室的落塵管理」主要影響的是異物遮光造成的「針孔、缺口（Mousebite）或斷線/短路」等點狀缺陷，並非控制整體均勻線路寬度（Trace Width）的主要常態製程調節因素。故選 A。\n【選項辨析】\n- (A) 無塵室落塵管理：正確答案（落塵主控點狀缺口/斷路短路，非整體線寬調整參數）。\n- (B) 蝕刻因子管控：直接決定垂直向下與橫向側蝕比率，重度影響頂層線寬。\n- (C) 曝光能量管控：決定光阻交聯寬度，直接決定顯影後線路寬度。\n- (D) 面銅銅厚均勻性：銅越厚需蝕刻時間越長，側蝕越多，顯著影響線寬。",
    "source_id": "pcb-7d782d02ff054a5d",
