    "stem": "針對軟板盲孔(Blind Via)的管理重點，下列何者有誤？",
    "question": "針對軟板盲孔(Blind Via)的管理重點，下列何者有誤？",
    "options": [
      "雷射打孔後要留意下孔徑管控在上孔徑的 80%左右或以上",
      "雷射打孔後須以化學高錳酸鹽進行除膠",
      "避免盲孔設計於高彎折應力區域",
      "管控盲孔是否孔偏"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】軟板聚醯亞胺（PI）盲孔雷射加工後之除膠渣（Desmear）工法。\n【正確答案說明】(B) 傳統硬板主要為環氧樹脂，可耐受強鹼性高錳酸鉀（KMnO4）化學氧化咬蝕除膠；但軟板的絕緣基材是聚醯亞胺（Polyimide, PI），PI 材料在強鹼性高錳酸鹽溶液中會發生嚴重的鹼性水解破壞或過度劣化，孔壁形貌極難控制。因此軟板雷射盲孔或通孔鑽孔後的除膠渣與孔底清潔，業界標準一律採用「乾式電漿（Plasma Desmear，通常為 CF4 + O2 氣體）」，而非化學高錳酸鹽濕製程。故 (B) 敘述錯誤。\n【選項辨析】\n- (A) 雷射孔下孔徑控制在孔上徑 80% 以上：敘述正確（確保電鍍填孔良好、無嚴重倒錐角）。\n- (B) 雷射打孔後以化學高錳酸鹽除膠：錯誤（正確答案）。軟板 PI 基材需採用電漿 Plasma 除膠，忌用強鹼高錳酸鉀。\n- (C) 避免盲孔設計於高彎折應力區：敘述正確（應力集中會導致孔底銅箔斷裂）。\n- (D) 管控盲孔是否孔偏：敘述正確（防止對位偏移破盤）。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
