    "stem": "針對具有頻繁插拔需求的產品設計中，其裝置設計之連接處銅面(Cu Pad)，下列何 種表面處理技術較為常見？",
    "question": "針對具有頻繁插拔需求的產品設計中，其裝置設計之連接處銅面(Cu Pad)，下列何 種表面處理技術較為常見？",
    "options": [
      "電鍍硬金",
      "化鍍軟金",
      "化鍍錫",
      "有機皮膜(OSP)"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】插拔金手指（Gold Finger）銅墊表面處理技術。\n【正確答案說明】(A) 針對具有頻繁插拔需求的連接器接口（如金手指、記憶卡接點、插拔排線金屬端子），其表面處理必須具備極高的硬度（Knoop 硬度 > 130~200 HK）與耐摩擦磨耗壽命。因此一律採用含有微量鈷（Co）或鎳（Ni）合金元素之「電鍍硬金（Hard Electrolytic Gold）」。化鎳浸金（ENIG）或化鍍軟金其金層太薄且質軟（純金），插拔數次即會刮穿磨損露銅。故選 A。\n【選項辨析】\n- (A) 電鍍硬金：正確。添加合金元素具有高耐磨硬度，為插拔端子標準首選。\n- (B) 化鍍軟金：純金質地柔軟，易被插針刮傷，主要用於打線（Wire Bonding）而非插拔。\n- (C) 化鍍錫：錫質軟且易氧化磨耗，插拔壽命極低。\n- (D) 有機皮膜(OSP)：極薄有機膜，插拔一次即刮除破壞。",
    "source_id": "pcb-7d782d02ff054a5d",
