    "stem": "有關化金的金層功能，下列何者有誤？",
    "question": "有關化金的金層功能，下列何者有誤？",
    "options": [
      "在 SMT 作業時，其與錫膏銲接時在錫與金的介面形成 IMC 合金層",
      "其為保護底下的鎳層，防止鎳層氧化或腐蝕",
      "不打零件的非銲接區其化金表面可與其它外部金屬件接觸，作為接觸導通",
      "對比其它鍍層更具抗氧化的功能"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】化鎳浸金（ENIG）焊接冶金反應中金層之角色與 IMC 生成機理。\n【正確答案說明】(A) 在 SMT 錫膏高溫迴焊焊接過程中，外表面的超薄金層（通常僅 1~3 μ-inch）會在熔融錫液接觸的瞬間（一秒內）極速溶解並擴散至焊錫體中（形成 AuSn4 金屬間化合物並均勻分散）。真正在銅墊介面提供阻障並與錫原子發生冶金反應形成 IMC（介金屬化合物，如 Ni3Sn4）的是「底部的化學鎳層」，而不是金層與錫在介面形成結合 IMC！若金層過厚還會引發嚴重的「金脆（Gold Embrittlement）」。故 (A) 稱金層與錫在介面形成 IMC 是錯誤的。\n【選項辨析】\n- (A) 錫膏焊接在錫與金介面形成 IMC：錯誤（正確答案）。金層迅速熔入錫中，介面 IMC 是錫與鎳形成的 Ni3Sn4。\n- (B) 保護底下的鎳層防止氧化腐蝕：敘述正確（浸金的唯一物理職責為保護化學鎳不被空氣鈍化）。\n- (C) 非焊接區金表面可作為導通接觸：敘述正確（耐氧化且接觸電阻極低）。\n- (D) 對比其它鍍層更具抗氧化功能：敘述正確（金為化學惰性貴金屬）。",
