    "stem": "下列何者與材料阻抗的因素影響最小？",
    "question": "下列何者與材料阻抗的因素影響最小？",
    "options": [
      "介質層厚度與介電系數",
      "孔壁厚度",
      "線寬",
      "面銅(電鍍銅與底銅總銅厚)銅厚度"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】傳輸線特性阻抗（Characteristic Impedance, Zo）影響幾何與介電因子。\n【正確答案說明】(B) 依據高頻微帶線（Microstrip）與帶狀線（Stripline）特性阻抗經驗公式（如 IPC-2141），阻抗 Zo 主要受以下幾何與材料變數決定：\n1. 介質層厚度（Dielectric Height, H）：正相關（H 越大，Zo 越高）；\n2. 介電常數（Dielectric Constant, Dk）：負相關；\n3. 信號線寬（Trace Width, W）：負相關（W 越大，電容效應越大，Zo 越低）；\n4. 面銅厚度（Trace Thickness, T）：負相關。\n而「孔壁厚度（Plated Hole Wall Thickness）」是導通孔之垂直結構，與平面分佈傳輸線本身的特性阻抗關係最小（甚至不直接出現在走線特性阻抗計算方程式中）。故選 B。\n【選項辨析】\n- (A) 介質層厚度與介電係數：為決定特性阻抗最關鍵核心因子。\n- (B) 孔壁厚度：正確答案（影響最小，非平面傳輸線阻抗計算參數）。\n- (C) 線寬：直接決定走線分佈電容與電感。\n- (D) 面銅厚度：直接決定導體幾何截面。",
