    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】電漿表面處理技術（Plasma）在 FPC 製程中之應用範疇。\n【正確答案說明】(D) 軟板工廠引進電漿設備（Plasma Cleaner），主要利用高能量活化氣體（如 Ar、O2、CF4）進行乾式物理微轟擊與化學自由基活化，其用途包括：\n1. 雷射盲孔孔底微量殘膠清除（Desmear）；\n2. 貼鋼片或 PI 補強板前之表面高分子改性，提高表面張力與膠水黏著強度；\n3. 多層軟板貫孔鑽孔後之孔壁去膠與微蝕清潔。\n而電路板線路製作在工業上皆採用化學濕蝕刻（酸性氯化銅或鹼性蝕刻液）或加成法電鍍，電漿各向同性氣相反應速率慢且無法低成本大規模移除數微米至數十微米的金屬銅箔，業界「不會使用電漿來蝕刻線路」。故 (D) 不是其主要功能。\n【選項辨析】\n- (A) 貼鋼片前清潔表面增加附著力：正確應用。\n- (B) 盲孔雷射後進行孔底除膠：核心重要應用。\n- (C) 多層軟板鑽孔後除膠清孔：標準工藝應用。\n- (D) 進行電漿蝕刻線路：錯誤（正確答案，非電漿之實際功能）。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-49b9921d3303d9b6a501735b",
    "content_hash": "3057c280e530779c12f787bdaa9617faadb1df3b76b7726d3d4a198a558ed1ea",
    "id": 64
