    "stem": "有關傳統蝕刻減層法的單面板流程，下列何者正確？",
    "question": "有關傳統蝕刻減層法的單面板流程，下列何者正確？",
    "options": [
      "發料→線路前處理→壓膜→曝光→顯影蝕刻去膜→保膠覆蓋膜壓合製程→化金 表面處理→文字→電測→外型→外觀終檢",
      "發料→線路前處理→壓膜→曝光→顯影蝕刻去膜→化金表面處理→保膠覆蓋膜 壓合製程→文字→外型→電測→外觀終檢",
      "發料→線路前處理→壓膜→曝光→顯影蝕刻去膜→保膠覆蓋膜壓合製程→化金 表面處理→文字→外型→電測→外觀終檢",
      "發料→線路前處理→壓膜→曝光→顯影蝕刻去膜→化金表面處理→保膠覆蓋膜 壓合製程→文字→電測→外型→外觀終檢"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】單面軟性電路板（Single-Sided FPC）傳統減除法標準生產流程。\n【正確答案說明】(C) 單面軟板傳統減除法標準製造工藝時序如下：\n1. 發料（開料）→ 2. 線路前處理（微蝕清洗）→ 3. 壓膜（貼乾膜）→ 4. 曝光 → 5. 顯影蝕刻去膜（洗出單面銅線路）→ 6. 保膠覆蓋膜壓合製程（Coverlay 假貼與熱壓，保護非焊接區線路）→ 7. 化金表面處理（露銅墊鍍金防氧化）→ 8. 網印文字 → 9. 外型加工（模具沖切或雷射割外型）→ 10. 電性測試（開短路測試）→ 11. 外觀終檢（FQC 目檢與包裝）。\n需特別注意：外型沖切後才能將多只成型軟板置入專用電測針模治具進行高精度電測；且表面處理化金必須在覆蓋膜壓合之後進行（覆蓋膜作為天然防鍍阻劑）。故 (C) 流程最為正確。\n【選項辨析】\n- (A) 電測在外型之前：單面板通常先沖外型再放電測模具，順序不當。\n- (B) 先化金再壓覆蓋膜：化金會在整條走線上鍍金，增加覆蓋膜剝離風險且徒增貴金屬成本，順序顛倒。\n- (C) 覆蓋膜壓合→化金→文字→外型→電測→外觀終檢：正確。\n- (D) 先化金再壓膜且電測在外型前：多處時序矛盾。",
