    "stem": "有關半加成法的優點與特性，下列何者有誤？",
    "question": "有關半加成法的優點與特性，下列何者有誤？",
    "options": [
      "半加成法針對細線路可提供較高良率的製作方式",
      "半加成法線路無塵室的曝光的異物髒點會造成線路缺口或斷線",
      "半加成法可提供線寬間距低於 35μm/35μm 的產品",
      "半加成法線路是電鍍方式鍍出來的，再經快速蝕刻去除底銅，其對於線路的側 蝕量較小"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】半加成法（mSAP）之微細線路製作特性與缺陷機理。\n【正確答案說明】(B)\n- 在「減除法（Subtractive）」中，乾膜覆蓋線路區，曝光區若有異物髒點遮光，乾膜未硬化顯影洗掉，蝕刻時銅被咬掉會造成「缺口或斷線」；\n- 但在「半加成法（mSAP）」中，製程剛好相反！乾膜是作為「電鍍阻劑（Plating Resist）」，線路區在曝光顯影後是「裸露開口」，要靠電鍍銅填入形成線路。若無塵室曝光時有異物髒點遮擋在非線路區，該處乾膜未曝光顯影被洗掉，後續電鍍時會長出異常銅塊，剝膜快蝕後反而形成「非線路區銅渣或短路（Bridge / Short）」，而不是線路缺口或斷線。因此 (B) 的因果敘述顛倒，為錯誤選項。\n【選項辨析】\n- (A) 針對細線路可提供較高良率：敘述正確（線寬可至 20~30 μm 以下）。\n- (B) 曝光異物髒點會造成缺口或斷線：錯誤（正確答案）。mSAP 下髒點導致誤電鍍銅，形成短路殘銅。\n- (C) 可提供線寬間距低於 35μm/35μm：敘述正確（mSAP 主戰場）。\n- (D) 電鍍成型後僅快蝕薄底銅，側蝕量極小：敘述正確（具優異垂直側壁）。",
