    "stem": "下列何者表面處理的方式比較少被應用在軟板上？",
    "question": "下列何者表面處理的方式比較少被應用在軟板上？",
    "options": [
      "化鎳金",
      "化鎳鈀金",
      "電鍍金",
      "有機保焊膜(Organic Solderability Preservatives，OSP)"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】軟性電路板表面處理技術之相容性與選用限制。\n【正確答案說明】(D) 有機保焊膜（OSP）是在銅表面生成一層有機化學錯合物薄膜。軟板具有多道熱壓合（如貼補強板、壓覆蓋膜）、多次高溫烘烤，且軟板結構組裝多需承受二次以上雙面高溫迴焊與手工補焊；OSP 耐高溫老化與耐熱衝擊能力極差，經一次熱壓或回焊後皮膜即裂解氧化，導致後續焊錫性急劇劣化。此外軟板金手指與按鍵區常需耐磨導通，OSP 完全無法提供接觸導通功能。因此軟板業界普遍採用化鎳金（ENIG）、化鎳鈀金（ENEPIG）或電鍍金，而極少採用「有機保焊膜（OSP）」。故選 D。\n【選項辨析】\n- (A) 化鎳金：軟板最標準常見之表面處理。\n- (B) 化鎳鈀金：具備極佳打線與 SMT 兼容性，廣泛應用於高階軟板。\n- (C) 電鍍金：金手指耐磨插拔必備工法。\n- (D) 有機保焊膜(OSP)：正確答案（軟板極少使用，耐熱壽命不足以支撐軟板後續熱壓製程）。",
