    "explanation": "【核心考點】負型乾膜光阻顯影液之化學主成份。\n【正確答案說明】(A) 印刷電路板線路製程所廣泛使用的負型乾膜光阻（Negative Dry Film），其未曝光區之聚合物含有大量酸性羧酸基（-COOH），需以弱鹼性水溶液中和轉化為可溶性羧酸鹽而溶解洗除。工業上標準顯影藥水的主成份為「0.8%～1.2% 之弱鹼性碳酸鉀（K2CO3）或碳酸鈉（Na2CO3）水溶液」。\n【選項辨析】\n- (A) 碳酸鉀或碳酸鈉：正確。弱鹼性碳酸鹽水溶液為負型乾膜標準顯影液。\n- (B) 過硫酸鉀或過硫酸鈉：為強氧化劑，用於銅表面微蝕咬銅，非顯影液。\n- (C) 氫氧化鉀或氫氧化鈉：為強鹼，會使乾膜整片溶脹剝落，是「剝膜液（Stripping）」而非顯影液。\n- (D) 硫酸加雙氧水：為酸性雙氧水微蝕藥水，非顯影液。",
