    "explanation": "【核心考點】乾膜顯影槽液濃度老化、副產物累積與定期換槽管理。\n【正確答案說明】(C) 在乾膜顯影過程中，未曝光的乾膜樹脂不斷被溶解入槽液中，使得槽內有機光阻固形物與界面活性劑濃度持續攀升、槽液消泡能力下降、比重與黏度劇增。即便有自動補充新鮮碳酸鈉與純水，當溶入的光阻樹脂累積達飽和極限時，顯影能力會嚴重鈍化且大量殘渣會回沾污染板面。因此顯影槽「絕不可能不定期換槽」，各廠 SOP 皆嚴格規定累積產出達一定面積或時間必須「定期當槽排空、徹底清洗槽壁並更換全槽新藥水」。故 (C) 敘述有誤。\n【選項辨析】\n- (A) 藥水濃度與溫度固定，依顯影點設定時間：敘述正確（一般顯影點控制在 40%~60% 處）。\n- (B) 反應時間決定線速度，不同乾膜速度不同：敘述正確。\n- (C) 只要自動添加與濃度分析即可不須定期換槽：錯誤（正確答案）。溶入有機殘膠過高時必須強制定期全槽換新。\n- (D) 當天開線前需化驗分析確認濃度：敘述正確（為確保品質之一級點檢流程）。",
