    "stem": "有關銅表面化學微蝕反應基本原理與功能，下列何者有誤？",
    "question": "有關銅表面化學微蝕反應基本原理與功能，下列何者有誤？",
    "options": [
      "普通稀硫酸也可以直接咬蝕銅面達到微蝕效果",
      "雙氧水系列的藥水是先以雙氧水來氧化銅層，再以硫酸將氧化銅去除",
      "過硫酸鹽系列的藥水咬銅後，需再以稀硫酸去除表面殘留的鹽類副產物",
      "微蝕的目的是產生新鮮沒有汙染的潔淨銅面 ，且具表面粗糙度來增加後續加工 物的附著力"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】銅面化學微蝕（Micro-etching）反應機構與無機酸氧化原理。\n【正確答案說明】(A) 銅（Cu）在金屬活動性順序表中位於氫（H）之後，標準電極電位為 +0.34 V，化學性質相對穩定。普通非氧化性酸（如稀硫酸、稀鹽酸）在常溫下「無法將零價金屬銅氧化溶解」，單純浸泡稀硫酸只具備清除銅表面氧化物（CuO / Cu2O 清潔酸洗）的功能，無法咬蝕金屬銅達到產生粗糙度之微蝕效果。微蝕藥水必須引入強氧化劑（如過硫酸鈉、過硫酸銨，或硫酸加雙氧水 H2O2）先將金屬銅氧化為銅離子，再經酸溶解配合生成硫酸銅。故 (A) 稱稀硫酸可直接微蝕咬銅是完全錯誤的。\n【選項辨析】\n- (A) 普通稀硫酸也可以直接咬蝕銅面達到微蝕效果：錯誤（正確答案）。稀硫酸無氧化能力無法咬蝕零價金屬銅。\n- (B) 雙氧水系列先以雙氧水氧化銅再由硫酸去除：敘述完全符合反應機理。\n- (C) 過硫酸鹽系列咬銅後需稀硫酸去除殘留鹽類副產物：敘述正確。\n- (D) 微蝕目的為產生潔淨新鮮粗糙銅面以增加附著力：微蝕製程之核心物理目的。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-cd028bbab188b173902192ca",
    "content_hash": "b349b7e18d77963dd867fd0b454015337cd73d750f5437fca5ef11e6b34c9695",
