    "pdf_num": 27,
    "stem": "有關銅表面化學微蝕速率(每分鐘的銅咬蝕量，單位 : μm/min)的敘述，下列何者 有誤？",
    "question": "有關銅表面化學微蝕速率(每分鐘的銅咬蝕量，單位 : μm/min)的敘述，下列何者 有誤？",
    "options": [
      "微蝕速率跟藥水濃度成正向關係",
      "管控二價銅離子含量(g / L)主因是銅離子含量會影響微蝕速率的穩定性",
      "微蝕速率跟藥水槽溫度成正向關係",
      "微蝕速率跟微蝕槽的反應時間成正比，微蝕的反應時間變兩倍時微蝕速率也變 成兩倍"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】化學微蝕速率（Rate）與微蝕總量之物理量因果關係。\n【正確答案說明】(D) 「微蝕速率（Micro-etch Rate）」的物理定義是「單位時間內的銅咬蝕深度」（例如 1.0 μm/min），代表反應進行的快慢；而「微蝕量（Total Etch Amount）」是總咬蝕深度，微蝕量 = 微蝕速率 × 反應時間。當板子在微蝕槽的反應時間延長為 2 倍時，在藥水濃度與溫度穩定的前提下，微蝕「總量」會變成 2 倍，但是「微蝕速率（每分鐘咬銅量）」依然保持不變！宣稱「反應時間變兩倍時微蝕速率也變成兩倍」是混淆了「速率」與「總量」的錯誤概念。故選 D。\n【選項辨析】\n- (A) 微蝕速率跟藥水濃度成正向關係：濃度越高碰撞機率越大，速率越快。\n- (B) 管控二價銅離子主因是其會影響反應速率穩定性：銅離子過高會催化雙氧水分解或抑制反應平衡。\n- (C) 微蝕速率跟槽液溫度成正向關係：溫度上升阿瑞尼斯活化分子數增加，反應加快。\n- (D) 反應時間變兩倍時微蝕速率也變成兩倍：錯誤（正確答案）。增加的是微蝕總量，反應速率本身不隨時間倍增。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
