    "stem": "RoHS 規定需管控如下物資含量不可超過限定標準，下列何者有誤？",
    "question": "RoHS 規定需管控如下物資含量不可超過限定標準，下列何者有誤？",
    "options": [
      "鎘",
      "鉛",
      "鐡",
      "六價鉻"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】歐盟 RoHS 環保指令限制有害物質清單。\n【正確答案說明】(C) 歐盟 RoHS 指令（Restriction of Hazardous Substances）初代管制六大有害物質包含：鉛（Pb）、鎘（Cd）、汞（Hg）、六價鉻（Cr6+）、多溴聯苯（PBB）、多溴二苯醚（PBDE）。其中「鐵（Fe）」為自然界豐富且無毒之普遍金屬元素，廣泛存在於各類設備機構件與合金材料中，絕對不是 RoHS 管制有害物質。故選 C。\n【選項辨析】\n- (A) 鎘：RoHS 重點管制重金屬（限值 < 100 ppm）。\n- (B) 鉛：RoHS 重點管制重金屬（無鉛製程管制，限值 < 1000 ppm）。\n- (C) 鐡：正確答案（非 RoHS 限制物質）。\n- (D) 六價鉻：RoHS 重點管制高毒性金屬（限值 < 1000 ppm）。",
