    "stem": "有關軟板鑽孔後孔壁金屬化的方法，下列何者有誤？",
    "question": "有關軟板鑽孔後孔壁金屬化的方法，下列何者有誤？",
    "options": [
      "黑影",
      "黑孔",
      "黑化",
      "化學銅"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】鑽孔後孔壁金屬化（Through-hole Metallization）工法分類。\n【正確答案說明】(C) 電路板鑽孔後使絕緣孔壁導電化的「孔壁金屬化」技術主要包括：\n1. 化學沉銅（PTH / Electroless Copper）；\n2. 碳黑直接電鍍法（如黑孔 Black Hole 製程）；\n3. 石墨直接電鍍法（如黑影 Shadow 製程）；\n4. 導電高分子法（Conductive Polymer）。\n而「黑化（Black Oxide / 棕化 Brown Oxide）」是內層多層板壓合前，在內層銅面上生長一層微觀樹枝狀銅氧化物以增強樹脂結合力的「銅面前處理工藝」，完全不是鑽孔後的孔壁金屬化導電技術。故 (C) 敘述有誤。\n【選項辨析】\n- (A) 黑影（Shadow）：石墨膠體直接導電化製程，屬孔金屬化工藝。\n- (B) 黑孔（Black Hole）：碳黑微粒孔壁導電化工藝。\n- (C) 黑化：錯誤（正確答案）。為內層壓合氧化粗化製程，非孔壁金屬化方法。\n- (D) 化學銅：最傳統且經典之化學沉銅金屬化方法。",
    "source_id": "pcb-7d782d02ff054a5d",
