    "stem": "在減層蝕刻法中，當採用傳統底面曝光方式的線路製程，下列何者不是造成非線 路區的銅渣或短路之原因？",
    "question": "在減層蝕刻法中，當採用傳統底面曝光方式的線路製程，下列何者不是造成非線 路區的銅渣或短路之原因？",
    "options": [
      "乾膜刮傷",
      "底片刮傷",
      "線路蝕銅不淨",
      "乾膜顯影不潔"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】減除法傳統底片曝光線路短路（Short）成因辨析。\n【正確答案說明】(A) 在減除法線路製程中，採用負片（Negative Film）曝光時，底片透明處透光使乾膜硬化保護銅線，不透光黑處則顯影去除並將銅蝕刻掉。若「乾膜表面刮傷」，在刮痕處乾膜變薄甚至脫落破裂，底下的銅在蝕刻時直接被蝕刻液咬破，形成的是線路「缺口或斷路（Open）」，絕非造成非線路區短路或殘銅。而非線路區產生短路/銅渣的原因是：底片刮傷透光使不該硬化的乾膜硬化（(B)）、蝕刻機咬蝕不徹底（(C)）或未曝光乾膜顯影殘留阻擋蝕刻（(D)）。故 (A) 不是短路原因。\n【選項辨析】\n- (A) 乾膜刮傷：正確答案（乾膜刮損造成保護失效，遭蝕刻後形成缺口或斷路，非短路）。\n- (B) 底片刮傷：遮光區漏光硬化乾膜，阻礙蝕刻形成殘銅短路。\n- (C) 線路蝕銅不淨：銅未咬穿造成導線間殘銅短路。\n- (D) 乾膜顯影不潔：殘膠遮擋蝕刻液，形成浮銅短路。",
