    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】半加成法（mSAP）電鍍抗蝕阻劑缺陷與短路機理。\n【正確答案說明】(B) 在半加成法（mSAP）中，線路區是透過顯影後將乾膜沖開露出底銅，再於凹槽中「電鍍銅」填實。若乾膜顯影失控造成「顯影不潔（線路凹槽底部有乾膜殘膠）」，底銅被殘膠遮蔽無法導電鍍上電鍍銅，後續快速蝕刻時凹槽更會被咬蝕，導致線路變細、缺口乃至「斷路（Open）」，絕不可能長出銅渣造成「短路（Short）」。造成 mSAP 短路的原因是非線路區乾膜破損、刮傷、曝光微塵遮光洗掉導致該處意外鍍上銅層（(A)、(C)），或差分快速蝕刻不足殘留底銅（(D)）。故選 B。\n【選項辨析】\n- (A) 曝光髒點：使非線路區乾膜意外被顯影溶除，電鍍銅長出引發短路。\n- (B) 乾膜顯影不潔：正確答案（殘膠阻擋電鍍，造成線路凹陷缺口或斷路，非短路）。\n- (C) 乾膜刮傷：阻劑破損使電鍍液侵入長銅引發短路。\n- (D) 快速蝕刻失控底銅蝕刻不淨：基板整面殘留微薄底銅引發微短路。",
