    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】整板電鍍（Panel Plating）電流設定與銅層厚度數學關係。\n【正確答案說明】(B) 在整板電鍍機台操作時，工程師需先輸入板材總電鍍面積 A_est，機台控制器依照預設電流密度 J_set（A/ft²）自動輸出總電鍍電流：I_total = J_set × A_est。\n若設定時「估算的電鍍面積比實際板子面積大」（即 A_est > A_real），則機台輸出的總電流 I_total 會比實際所需電流更大，導致實際流過板子單位面積的「實際電流密度 J_real = I_total / A_real 大於設定值」，在固定的電鍍時間下，鍍出的銅層厚度反而會「偏厚（超厚）」，而不是造成銅層厚度不足！故 (B) 不是造成厚度不足的原因。\n【選項辨析】\n- (A) 電鍍溶液溫度異常：可能影響導電度或陽極極化，影響沉積效率。\n- (B) 估算電鍍面積比實際面積大：正確答案（估算面積偏大會導致總電流給過多，鍍銅層過厚而非不足）。\n- (C) 電鍍掛架接觸不良：接觸電阻大，流過電流不足，鍍銅過薄。\n- (D) 流經板子電流不足：直接導致法拉第沉積量不足，鍍層過薄。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-ef4610c15f614ea050475215",
    "content_hash": "6d2f29f89d999ad9d6ef095258b94e9a2372e0ee3e4e1e5bdd9cecc3169dd8cb",
    "id": 78
