    "stem": "基板材料的熱裂解溫度(Td 值)是用下列何種儀器量測？",
    "question": "基板材料的熱裂解溫度(Td 值)是用下列何種儀器量測？",
    "options": [
      "TGA",
      "萬能拉力機",
      "FTIR",
      "GPC"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】熱重分析儀（TGA）量測熱裂解溫度（Td）。\n【正確答案說明】(A) TGA（Thermogravimetric Analysis，熱重分析儀）在程序控溫下連續量測樣品隨溫度上升產生的質量變化。當材料受熱開始發生分子鏈熱分解、揮發性小分子逸散，其重量損失達特定百分比（通常為失重 5%）時的對應溫度，即定義為「熱裂解溫度（Decomposition Temperature, Td）」。\n【選項辨析】\n- (A) TGA：正確。熱重分析儀是量測熱失重與材料熱裂解溫度 Td 的標準指定設備。\n- (B) 萬能拉力機：量測抗拉強度、伸長率與銅箔剝離強度（Peel Strength）。\n- (C) FTIR：傅立葉紅外光譜儀，用於高分子化學官能基定性分析。\n- (D) GPC：凝膠滲透層析儀，用於測定高分子分子量分佈。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-4246af3811b0b766d9547162",
    "content_hash": "e2eb39508e0656a11571c2daf12db39982f3360888ff90b2785040669bd946b4",
    "id": 79
