    "num": 35,
    "display_num": 35,
    "pdf_num": 35,
    "stem": "1 盎司(oz)銅箔的厚度=34~35μm 左右是指 1 盎司的銅箔總重量平鋪在多大的面積 範圍之內所得到的厚度？ (銅箔密度=8.93 公克/立方公分，1 盎司重量=28.35 公克)",
    "question": "1 盎司(oz)銅箔的厚度=34~35μm 左右是指 1 盎司的銅箔總重量平鋪在多大的面積 範圍之內所得到的厚度？ (銅箔密度=8.93 公克/立方公分，1 盎司重量=28.35 公克)",
    "options": [
      "1 square inch (平方英寸)",
      "1 square dm (平方分米=10cmX10cm)",
      "1 square feet (平方英尺)",
      "1 square meter (平方公尺)"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】印刷電路板產業標準 1 盎司（oz）銅箔厚度之物理換算定義。\n【正確答案說明】(C) PCB 業界定義「1 oz 銅箔」的標準基準為：將重量為 1 盎司（1 avoirdupois ounce = 28.3495 公克）的高純度金屬銅，均勻鋪展平舖在「1 平方英尺（1 square foot = 1 ft² = 12 in × 12 in = 929.03 cm²）」的面積上所形成的均勻幾何厚度。\n依據銅密度 ρ = 8.93 g/cm³ 計算：厚度 H = 質量 / (面積 × 密度) = 28.35 g / (929.03 cm² × 8.93 g/cm³) ≈ 0.003417 cm ≈ 34.2 μm（約 1.35 mil，公稱 34~35 μm）。故標準鋪展基準面積為 1 平方英尺。故選 C。\n【選項辨析】\n- (A) 1 square inch：面積太小，若鋪在 1 平方英吋厚度將高達數公釐。\n- (B) 1 square dm：100 cm²，計算數值不符。\n- (C) 1 square feet：正確。1 平方英尺（約 929 cm²）為國際法定換算標準面積。\n- (D) 1 square meter：1 平方公尺面積太大，鋪展厚度僅約 3 μm。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
    "question_uid": "pcb-bdea964ddc4ac968bdd3a461",
    "content_hash": "11d06a1b09031bfcd21fbcfc1ad986cc84bd4450c4405c9b47d94344159607d6",
    "id": 80
