    "stem": "線路製程的乾膜貼附時，影響乾膜附著力的重點有下列哪些？",
    "question": "線路製程的乾膜貼附時，影響乾膜附著力的重點有下列哪些？",
    "options": [
      "板面是否氧化或水氣未烘乾",
      "壓膜速度的管控",
      "壓膜溫度的管控",
      "壓膜壓力的管控"
    ],
    "answer": "ABCD",
    "ans_text": "標準答案：(ABCD)",
    "is_multiple": true,
    "explanation": "【核心考點】乾膜壓膜（Lamination）製程影響光阻附著力之四大關鍵控制參數。\n【正確答案說明】(ABCD) 乾膜貼附在銅箔表面，依賴高分子熱熔黏著劑填入微觀微蝕凹凸峰谷中形成機械錨定鍵結：\n- (A) 板面氧化或水氣：氧化層極易在顯影蝕刻時脫落，殘留水氣在熱壓滾輪高溫下汽化形成微氣泡，破壞附著力（正確）。\n- (B) 壓膜速度：速度過快時膠層軟化流動時間不足，潤濕性不良引發邊緣空隙（正確）。\n- (C) 壓膜溫度：溫度決定光阻黏彈態流動性，溫度不足膠層太硬無法咬入銅面微孔，溫度過高光阻老化熱交聯（正確）。\n- (D) 壓膜壓力：壓力提供排氣推力，確保抗蝕膜緊密緊貼（正確）。\n因此四者皆為影響乾膜附著力之核心重點。故選 ABCD。\n【選項辨析】\n- (A) 正確：清潔乾燥為附著前提。\n- (B) 正確：決定熱量傳遞與膠體流動時間。\n- (C) 正確：活化熱熔膠層流動性。\n- (D) 正確：施加足夠法向應力消除微觀氣隙。",
    "source_id": "pcb-7d782d02ff054a5d",
