    "stem": "下列哪些是軟板用來遮蔽、保護及防止特定銅面在迴焊或波焊製程中接觸到焊 錫？",
    "question": "下列哪些是軟板用來遮蔽、保護及防止特定銅面在迴焊或波焊製程中接觸到焊 錫？",
    "options": [
      "覆蓋膜(Coverlay)",
      "化金區",
      "鋼片",
      "防焊油墨"
    ],
    "answer": "AD",
    "ans_text": "標準答案：(AD)",
    "is_multiple": true,
    "explanation": "【核心考點】軟性電路板防焊遮蔽與表面保護材料。\n【正確答案說明】(AD) 在軟板製程中，保護外層銅線避免氧化刮傷，並在波焊或高溫迴焊時「防止特定非焊接區銅面接觸焊錫」的遮蔽絕緣材料主要有兩種形式：\n1. (A) 覆蓋膜（Coverlay）：傳統軟板最主要的保護層，由 PI 薄膜配合膠系開模沖出焊墊孔後貼合壓製；\n2. (D) 防焊油墨（Flexible Solder Mask）：適用於微細間距、高密度線路之液態感光軟板專用耐彎折油墨。\n化金區是待焊接或接觸導電區（(B)非遮蔽材）；鋼片為機械支撐補強材（(C)非防焊遮蔽材）。故答案為 AD。\n【選項辨析】\n- (A) 覆蓋膜(Coverlay)：正確。軟板經典之絕緣防焊耐折保護膜。\n- (B) 化金區：為金屬導電層，非絕緣防焊材。\n- (C) 鋼片：提供剛性支撐之結構材料。\n- (D) 防焊油墨：正確。軟板微細線路常用之感光遮蔽防焊材。",
