    "explanation": "【核心考點】軟板/多層板成品總板厚規格之控制因素。\n【正確答案說明】(ACD)\n- (A) 疊層材料厚度規格：PI 膜厚、銅箔厚度、補強板及膠層的厚度規格是決定成品厚度的最直接基礎（正確）。\n- (C) 電鍍厚度：孔銅與面銅電鍍之鍍層厚度（如電鍍增加 15~25 μm）直接疊加在總板厚上（正確）。\n- (D) 壓合參數管控：壓合溫度、升溫速率與壓力大小決定膠層溢膠厚度損失與流動壓縮比，直接影響最終熱壓成型總厚度（正確）。\n而材料的「廠牌（Brand）」只是品牌名稱，在同等型號與物理厚度規格管制下，廠牌名稱本身不是影響板厚的技術控制物理因子。故影響板厚的因素為 ACD。\n【選項辨析】\n- (A) 正確：原始材料厚度規格為幾何厚度骨架。\n- (B) 錯誤：材料品牌非決定物理厚度之參數。\n- (C) 正確：金屬電鍍沉積增厚直接影響外層厚度。\n- (D) 正確：熱壓流膠壓縮程度直接決定介質層最終厚度。",
