    "explanation": "【核心考點】軟板貼合補強鋼片搭配導電膠（Conductive Adhesive）之雙重機能。\n【正確答案說明】(AC) 在軟板特定區域貼合不鏽鋼片（SUS Stiffener）時，若使用含金屬導電微粒（銀粉或鎳粉）之「導電膠」取代一般絕緣純膠，其主要發揮兩大作用：\n1. (A) 接地導通：使導電鋼片與軟板內部接地層（GND）電氣相連，提供大面積低阻抗接地路徑，大幅增強抗電磁干擾（EMI Shielding）能力；\n2. (C) 強化固定：提供高硬度與高抗彎曲剛性，支撐連接器插拔或元器件承載，防止軟板變形損壞。\n鋼片與膠膜均貼於內部或局部，不具備增加產品亮度或擋強光功能。故答案為 AC。\n【選項辨析】\n- (A) 接地導通：正確。導電膠打通金屬補強片與電路 GND 實現電磁屏蔽與防靜電。\n- (B) 錯誤：非光學顯示元件。\n- (C) 強化固定：正確。鋼片最核心之機械補強與抗插拔扭曲機能。\n- (D) 錯誤：無光學遮光設計關聯。",
