    "ans_text": "標準答案：(BC)",
    "is_multiple": true,
    "explanation": "【核心考點】高動態耐彎折雙面軟板之「選鍍（Button Plating）」特殊製程。\n【正確答案說明】(BC) 雙面軟板為了達到百萬次動態耐彎折壽命，彎折區域的走線必須維持原始壓延退火銅（RA銅）單純厚度，絕不能鍍上結晶脆硬之二次電鍍銅：\n- (B) 選鍍只鍍孔壁與孔環，其它區域不電鍍：選鍍技術透過專用乾膜遮蔽整個線路區與動態彎折區，僅露出貫通孔與孔周圍微小孔環（Pad）進行電鍍銅加厚，確保導通可靠同時保持線路區無電鍍銅（正確）；\n- (C) 選鍍前與蝕刻前需各做一次線路曝光流程：第一次曝光為「選鍍孔保護乾膜曝光」，電鍍完後剝膜；第二次曝光為「線路蝕刻乾膜曝光」，顯影後進行線路蝕刻（正確）。\n(A) 稱專對彎折區線路電鍍是完全相反的（彎折區絕對禁止電鍍）；(D) 選鍍乾膜要求高耐酸耐電鍍性，與普通蝕刻乾膜特性需求不同。故答案為 BC。\n【選項辨析】\n- (A) 錯誤：彎折區嚴禁電鍍銅，否則彎折耐疲勞壽命大跌。\n- (B) 正確：僅針對導通孔壁與孔環電鍍，保留走線之高延展原銅。\n- (C) 正確：需分別進行「選鍍圖案」與「線路蝕刻圖案」兩次曝光。\n- (D) 錯誤：兩道製程耐電鍍與耐化學性要求不同，需搭配適當乾膜。",
    "source_id": "pcb-7d782d02ff054a5d",
    "source_version": "official-115-01",
