    "ans_text": "標準答案：(BD)",
    "is_multiple": true,
    "explanation": "【核心考點】化學鎳鈀金（ENEPIG）表面處理之反應機理與打線特性。\n【正確答案說明】(BD) ENEPIG（Electroless Nickel Electroless Palladium Immersion Gold）表面結構為鎳層/化學鈀層/浸金層：\n- (A) 敘述有誤：沉積化學鈀層是採用含有還原劑（如次磷酸鹽或甲酸）之化學鍍還原液，使鈀離子受還原劑催化在鎳表面自催化析出，絕不是靠鈀離子直接腐蝕咬蝕鎳層之置換反應（置換會像浸金腐蝕鎳造成黑鎳一樣劣質）；\n- (B) 敘述正確：鈀沉積原理是利用還原劑自催化還原，非咬蝕鎳層；\n- (D) 敘述正確：中間純鈀層能完全阻絕鎳原子向外擴散，具備極佳的打線銲接性能，非常適合金線、銅線及鋁線之晶片打線作業（Wire Bonding）。\nENEPIG 亦高度適合 SMT 焊接（(C)稱不適合為錯誤）。故正確答案為 BD。\n【選項辨析】\n- (A) 錯誤：非置換咬蝕反應。\n- (B) 正確：採用化學還原型（Autocatalytic Electroless）沉積鈀層。\n- (C) 錯誤：為通用性極佳之 Universal Finish，高度適合 SMT。\n- (D) 正確：為金線/鋁線/銅線晶片封裝打線之頂級首選。",
