    "stem": "有關軟板與硬板在鑽孔到除膠渣流程，下列哪些敘述有誤？",
    "question": "有關軟板與硬板在鑽孔到除膠渣流程，下列哪些敘述有誤？",
    "options": [
      "機械鑽孔或雷射鑽孔後的的除膠渣製程，軟板與硬板一樣走高錳酸鹽化學除膠 方式",
      "軟板採電漿方式來除膠渣",
      "雙面軟板的通孔在鑽孔後可考慮免走除膠渣製程，而直接進行孔壁金屬化",
      "盲孔打完雷射後無須進行孔底清孔，可以直接進行孔壁金屬化"
    ],
