    "ans_text": "標準答案：(AD)",
    "is_multiple": true,
    "explanation": "【核心考點】軟板與硬板鑽孔後除膠渣（Desmear）工法差異。\n【正確答案說明】(AD)\n- (A) 敘述有誤（符合題意）：軟板基材主要為聚醯亞胺（PI），PI 膜在強鹼性高錳酸鹽溶液中會發生劇烈水解溶解腐蝕，孔壁極易變形，因此軟板除膠渣「不能採用化學高錳酸鹽法」，而必須採用氣體電漿法（Plasma）；\n- (D) 敘述有誤（符合題意）：盲孔打完雷射後，孔底受熱熔融會殘留一層極薄的樹脂碳化碎屑與浮膠（Smear），若不經電漿清孔徹底清潔孔底銅面，電鍍銅將無法與底銅形成微觀金屬鍵結，組裝受熱時孔底會全數分層脫落（Blind Via Separation），因此「必須進行孔底清潔」。\n(B) 軟板採電漿除膠、(C) 雙面普通通孔要求不高時可評估免化學除膠，皆為正確敘述。題目問哪些有誤，故選 AD。\n【選項辨析】\n- (A) 錯誤敘述（答案）：軟板禁用高錳酸鹽濕除膠，需用電漿。\n- (B) 正確敘述：電漿為軟板除膠標準主流。\n- (C) 正確敘述：雙面純通孔若排屑良好有機會直接活化電鍍。\n- (D) 錯誤敘述（答案）：雷射盲孔孔底極髒，嚴禁免清孔直接電鍍。",
