    "pdf_num": 8,
    "stem": "軟板過去在行動通訊及穿戴式電子裝置產品上扮演重要的地位，近來 AI 產業的蓬 勃發展，帶動包括高效運算、機器人、智慧製造、自動駕駛及無人載具等的應 用，因應此產業變化，軟板未來的技術發展趨勢有下列哪些？",
    "question": "軟板過去在行動通訊及穿戴式電子裝置產品上扮演重要的地位，近來 AI 產業的蓬 勃發展，帶動包括高效運算、機器人、智慧製造、自動駕駛及無人載具等的應 用，因應此產業變化，軟板未來的技術發展趨勢有下列哪些？",
    "options": [
      "高頻高速",
      "高密度細線",
      "立體組裝",
      "高散熱"
    ],
    "answer": "ABCD",
    "ans_text": "標準答案：(ABCD)",
    "is_multiple": true,
    "explanation": "【核心考點】AI、高算力與車載驅動下軟板（FPC）未來四大技術發展趨勢。\n【正確答案說明】(ABCD) 近年來隨著 AI 伺服器高頻傳輸、人形機器人多自由度關節、自動駕駛光達及無人機的爆發式成長，軟板面臨全新技術升級：\n- (A) 高頻高速：採用低損耗介質材料（如 LCP 液晶高分子、改性聚醯亞胺 MPI），降低高速傳輸損耗；\n- (B) 高密度細線：導入 mSAP 半加成法與雷射微孔，線寬線距向 L/S < 25/25 μm 突破；\n- (C) 立體組裝：複雜折疊與多層軟硬結合板（Rigid-Flex），實現狹窄異形機構空間之立體三維互連；\n- (D) 高散熱：結合金屬基板、內嵌銅塊或高導熱膠膜，解決高算力晶片局部過熱問題。\n四項皆為當前與未來軟板的核心技術演進方向。故選 ABCD。\n【選項辨析】\n- (A) 正確：應對 AI 與高速信號傳輸要求。\n- (B) 正確：微型化與微間距封裝需求。\n- (C) 正確：穿戴與機器人異形動態機構需求。\n- (D) 正確：車載與高功率模組熱管理需求。",
