    "stem": "有關異方性導電膠膜(Anisotropic Conductive Film， ACF)之敘述，下列哪些正 確？",
    "question": "有關異方性導電膠膜(Anisotropic Conductive Film， ACF)之敘述，下列哪些正 確？",
    "options": [
      "只能將導體與導體間互相連結導通",
      "能將零件與導體或者導體與導體間互相連結導通",
      "一定壓合條件下，X、Y 軸平面電氣互相導通，Z 軸方向上下則絕緣",
      "一定壓合條件下 Z 軸方向電氣進行上下導通，X、Y 軸平面則互相絕緣"
    ],
    "answer": "BD",
    "ans_text": "標準答案：(BD)",
    "is_multiple": true,
    "explanation": "【核心考點】異方性導電膠膜（ACF）之結構原理與導通導向性。\n【正確答案說明】(BD) ACF（Anisotropic Conductive Film）是由高分子絕緣接著劑與微米級導電導電粒子（如金屬球或鍍金/鎳高分子球）混煉製成的薄膜：\n- (B) 應用廣泛：可將細間距電子元件（如 LCD 驅動 IC、晶片端子）與軟板連接，亦可用於軟板與軟板或軟板與玻璃基板間的電氣連結（正確）；\n- (D) 導電各向異性：在熱壓頭施加適當溫度與垂直壓力下，Z 軸垂直方向的導電粒子被壓扁互鎖形成「金屬導通」，而在 X-Y 水平平面方向，導電粒子密度未達連通臨界值，依然被高分子環氧膠包覆隔絕，維持絕緣（正確）。\n(A) 稱只能連接導體與導體是狹隘的（廣泛用於零件/晶片與導體）；(C) 導向完全相反。故正確答案為 BD。\n【選項辨析】\n- (A) 錯誤：亦可連接晶片 IC 與基板導體（COG / COF 工藝）。\n- (B) 正確：具多元互連能力。\n- (C) 錯誤：XY 平面導通會導致嚴重相鄰短路。\n- (D) 正確：Z 軸垂直導通，XY 水平平面維持絕緣。",
