    "ans_text": "標準答案：(CD)",
    "is_multiple": true,
    "explanation": "【核心考點】軟性銅箔基板（FCCL）標準原材捲料寬度規格。\n【正確答案說明】(CD) 軟性銅箔基板（FCCL）以卷對卷（Roll-to-Roll）生產時，國際原廠捲料（Roll Laminate）有數種主流標準寬幅規格，最為通用且標準的工業規格寬幅為「250 mm（約 10 英吋規格）」以及「500 mm（約 20 英吋規格）」，兩者亦是各大卷對卷曝光機、塗佈機與沖孔機的標準設計軌道寬度。150 mm 與 400 mm 均非標準規格寬幅。故選 CD。\n【選項辨析】\n- (A) 150mm：非主要常規原材捲料規格。\n- (B) 400mm：非標準捲材寬度。\n- (C) 250mm：正確。軟板業界極普遍之 250 mm 捲料標準寬幅。\n- (D) 500mm：正確。標準半米寬 500 mm 高效大寬幅捲料。",
