    "pdf_num": 2,
    "stem": "電子元件會選擇焊接在硬板的因素中，下列何者有誤？",
    "question": "電子元件會選擇焊接在硬板的因素中，下列何者有誤？",
    "options": [
      "搭配超薄材料，可應用在超薄型化的產品中",
      "可選擇耐高溫與高頻高速的材料",
      "機械支撐能力優越",
      "如有細線路需求可搭 M-SAP 製程"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】電子元件選擇焊接於剛性電路板（硬板）之核心物理限制與特性。\n【正確答案說明】(A) 「超薄型化（Ultra-thin）」產品（如智慧手錶、折疊手機絞鏈連接線、超薄穿戴裝置）要求整體厚度極薄且能隨機構彎折，其必須依賴軟性電路板（FPC）或超薄軟膜；而硬質電路板（硬板）由玻纖布與樹脂增強層組成，標準厚度多在 0.4 mm 至 3.2 mm 以上，雖然有薄型硬板，但在追求極致超薄柔軟的應用場景中絕非硬板之主要優點與選擇因素。故 (A) 敘述有誤。\n【選項辨析】\n- (A) 搭配超薄材料，可應用在超薄型化的產品中：錯誤（正確答案，此為軟板核心特色，非硬板優勢）。\n- (B) 可選擇耐高溫與高頻高速材料：硬板材料體系多元（如高頻 PTFE、碳氫樹脂、低損耗級玻纖布）。\n- (C) 機械支撐能力優越：硬板剛性極佳，能穩定承載大型 BGA、散熱片與重型元件。\n- (D) 細線路需求可搭 M-SAP 製程：硬板高階 HDI 與載板廣泛採用改良型半加成法。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-4b7944f8f086a4e380ad4525",
    "content_hash": "cabafb07fa512eca95215395230f478d8e6cde4e3e160f3be0aeacec46d5da16",
    "id": 92
