    "is_multiple": false,
    "explanation": "【核心考點】印刷電路板基材分類：硬板材料 vs 軟板高頻材料。\n【正確答案說明】(D)\n- 剛性硬板常見基材包括：FR-4（環氧樹脂/玻纖布）、CEM-3（複合基板）、陶瓷基板（氧化鋁/氮化鋁，用於大功率散熱）、BT 樹脂（雙馬來醯亞胺三嗪，載板基材）與 ABF（味之素增層膜，高階覆晶載板）；\n- LCP（Liquid Crystal Polymer，液晶高分子）：為熱塑性芳香族聚酯薄膜，具有極低的介電損耗（Df < 0.002）與極低吸濕性，主要作為「高頻高速軟性電路板（Flexible PCB / 毫米波天線傳輸線）」之核心絕緣基材，並非硬板所使用的基材。故選 D。\n【選項辨析】\n- (A) 陶瓷基板：大功率 LED 與功率模組常用的剛性高導熱基板。\n- (B) BT 材 & ABF：半導體晶片封裝載板之剛性核心基板與增層材料。\n- (C) FR-4 & CEM-3：最普遍標準之剛性硬板基材。\n- (D) LCP：正確答案（為軟性高頻基材，非硬板基材）。",
