    "stem": "影響電鍍銅厚度的電鍍參數，下列敘述何者有誤？",
    "question": "影響電鍍銅厚度的電鍍參數，下列敘述何者有誤？",
    "options": [
      "鍍銅的厚度取決於電鍍時間與電流密度",
      "在固定的電流之下電流密度跟電鍍面積成正比",
      "在電流值固定與電鍍時間固定之下，鍍銅的厚度與電鍍面積成反比",
      "鍍銅的厚度與電流值成正比"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】電鍍電流密度、電流值與電鍍面積之反比定義關係。\n【正確答案說明】(B) 電流密度（Current Density, J）的物理定義為「單位電鍍面積上通過的電鍍電流」，公式為：J = I / A，其中 I 為總電流，A 為電鍍有效表面積。\n當「在固定的電流 I 之下」，電鍍面積 A 越大，單位面積分攤到的電流越小，即「電流密度 J 與電鍍面積 A 成反比」！故 (B) 稱電流密度跟電鍍面積成正比是完全相反的錯誤敘述。\n【選項辨析】\n- (A) 鍍銅厚度取決於時間與電流密度：完全正確（法拉第定律：厚度 d ∝ J × t）。\n- (B) 在固定的電流之下電流密度跟電鍍面積成正比：錯誤（正確答案，J = I/A 應成反比）。\n- (C) 在電流與時間固定下厚度與面積成反比：完全正確（面積越大沉積越薄）。\n- (D) 鍍銅厚度與電流值成正比：面積固定時，電流越大厚度越厚。",
