    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】PCB 開短路電性測試機台（ET / BBT）測試邊界與極限。\n【正確答案說明】(C) 電路板製造廠的專用電測機（Dedicated E-Tester）或飛針電測機（Flying Probe），主要利用低壓導通閾值（如 10~50 Ω 判定斷路/孔破）與高壓絕緣電阻測試（如 100~250 V、10~100 MΩ 判定相鄰導線微短路）。而「離子遷移（Electrochemical Migration, ECM / CAF 導電陽極絲）」是指在長期高溫高濕與連續直流電壓偏壓作用下，銅離子沿玻纖束或微裂隙發生緩慢電化學溶解與還原析出的「長期可靠度失效行為」，在出廠常溫常態下的瞬間瞬時電測機台上完全無法被單獨直接檢測出來（必須依賴實驗室專用的 THB / CAF 恆溫恆濕高壓監控設備）。故選 C。\n【選項辨析】\n- (A) 孔破：嚴重孔破會使孔電阻無窮大或超標，電測能直接測出開路斷路。\n- (B) 微短路：電測機高壓絕緣測試可檢測出微短路漏電。\n- (C) 離子遷移：正確答案（屬於環境應力長期潛在可靠度劣化現象，常溫瞬態電測無法檢出）。\n- (D) 微斷路：電測機導通阻抗測試能檢測出微斷路阻抗異常。",
