    "stem": "電路板之板厚英制單位是以 mil 為單位，例如板厚為 20~80mil，則 1 mil 等於多 少 μm？",
    "question": "電路板之板厚英制單位是以 mil 為單位，例如板厚為 20~80mil，則 1 mil 等於多 少 μm？",
