    "explanation": "【核心考點】電路板厚度英制單位 mil 與公制微米（μm）之標準換算。\n【正確答案說明】(A) 1 mil（又稱毫英吋）定義為千分之一英吋（0.001 inch）。換算為公制微米：1 mil = 0.001 × 25.4 mm = 0.0254 mm = 25.4 μm。題目取整數近似值即為「25 μm」。\n【選項辨析】\n- (A) 25：正確。1 mil ≈ 25.4 μm。\n- (B) 50：相當於 2 mil。\n- (C) 100：相當於 4 mil。\n- (D) 250：相當於 10 mil。",
