    "explanation": "【核心考點】剛性硬板相較於軟性電路板之根本結構優勢。\n【正確答案說明】(B) 剛性電路板（硬板）是以厚型環氧樹脂玻纖布基板經高壓壓合固化而成，具有極高的彎曲模數（Flexural Modulus）與剛性硬度，其最核心且優於軟板的本質優點就是「板材強度高且具備優異的機械支撐性能」，能夠穩固支撐大型多腳位 BGA、重型散熱片、高壓電容與連接器而不變形。故選 B。\n【選項辨析】\n- (A) 可走密集線路設計：軟板與硬板均能透過 HDI/mSAP 實現密集微細線路，非硬板單獨優勢。\n- (B) 板材強度高且具備機械支撐性能：正確。為硬板本質特徵。\n- (C) 可以達到高透明效果：硬板含玻纖布且不具透明性。\n- (D) 可耐高溫高濕環境使用：軟板 PI 基材耐熱性（Tg > 300°C）甚至高於多數普通硬板。",
