    "stem": "有關防焊油墨假性露銅的因素，下列何者有誤？",
    "question": "有關防焊油墨假性露銅的因素，下列何者有誤？",
    "options": [
      "銅厚度局部太薄引起",
      "油墨印太薄",
      "擋點網板因為印刷偏移造成油墨下墨量不足",
      "印刷網板堵塞導入下墨量不足"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】防焊製程「假性露銅（False Copper Exposure）」之成因分析。\n【正確答案說明】(A) 「假性露銅」是指在焊墊邊緣或銅線轉角處，防焊油墨並未完全開口露出銅面，但由於特定缺陷使油墨層極薄或遮蓋邊緣錯位，外觀看似露銅：\n- (B) 油墨印太薄：油墨在銅導線稜角（Corner）處發生表面張力回縮（Pullback），形成極薄邊緣膜厚，視覺與檢驗呈現假性露銅；\n- (C) 擋點網板印刷偏移：阻劑位置對位偏差，使線路邊緣油墨下墨量嚴重不足；\n- (D) 印刷網板堵塞：網孔出墨量受阻，塗覆覆蓋厚度不足。\n而 (A)「銅厚度局部太薄」只會使油墨更容易完全爬覆平坦化，銅線越矮越不易產生邊緣拉薄露銅，絕不可能因為銅太薄而引起假性露銅。故 (A) 敘述有誤。\n【選項辨析】\n- (A) 銅厚度局部太薄引起：錯誤（正確答案）。銅厚太薄不會導致假性露銅，銅厚過高稜角過陡才易回縮露銅。\n- (B) 油墨印太薄：稜角處漆膜過薄直接透光露銅。\n- (C) 擋點網板印刷偏移下墨量不足：局部遮蓋缺陷。\n- (D) 印刷網板堵塞下墨量不足：油墨缺墨引發局部露銅。",
