    "stem": "有關薄硬板加工時的設備的特性，下列何者有誤？",
    "question": "有關薄硬板加工時的設備的特性，下列何者有誤？",
    "options": [
      "水平設備考量薄型化來調整滾輪採密集小間距輪片與承載裝置",
      "水平設備須可調低噴壓減少卡板",
      "薄硬板可搭配卷對卷連續生產",
      "垂直設備可搭配防卡板掛架來支撐防止卡板"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】薄型剛性板（Thin Rigid Core）加工設備特性與卷對卷（R2R）相容性。\n【正確答案說明】(C) 「卷對卷（Roll-to-Roll, R2R）連續生產」必須要求基材具有高度的柔韌性、可連續彎曲收卷與放卷（如軟板 FCCL 捲材）；剛性薄硬板（如 0.05~0.1 mm FR-4 玻纖薄板）雖然較薄，但其基材內部仍含有縱橫交織的脆性玻璃纖維布，一旦強行彎曲捲繞，玻璃纖維束會立即產生微觀斷裂（Crazing）、折斷或爆板分層，因此剛性板「絕對無法搭配卷對卷（R2R）生產」，一律必須維持單片片狀（Panel-to-Panel）傳輸加工。故 (C) 敘述有誤。\n【選項辨析】\n- (A) 水平設備調整為密集小間距輪片：敘述正確（防止薄板在輪間下垂卡板）。\n- (B) 水平設備調低噴壓減少卡板：敘述正確（過大噴壓會將薄板吹翻掀起）。\n- (C) 薄硬板可搭配卷對卷連續生產：錯誤（正確答案）。剛性玻纖基材無法捲曲收卷，不可使用 R2R。\n- (D) 垂直設備搭配防卡板掛架支撐：敘述正確（增加剛性防漂浮）。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-afe46b595799907bf31fa7a8",
    "content_hash": "c3518a411d8429e450ac20cbb92d8c1020b27461c2387b0575360574a3a0c80c",
    "id": 100
