    "explanation": "【核心考點】硬板未來高階技術演進方向與熱力學指標要求。\n【正確答案說明】(B) 隨著 AI 高算力晶片、無鉛焊接高溫化（260°C）與高多層伺服器板發展，硬板材料必須具備極高的耐熱衝擊能力，因此業界技術一律要求「朝 High Tg（高玻璃轉化溫度，Tg ≥ 170~200°C 以上）方向發展」，藉以降低熱膨脹與防止分層爆板。宣稱「朝 Low Tg 點發展」是完全反向逆行的荒謬敘述。故選 B。\n【選項辨析】\n- (A) 朝高頻高速性能發展：主流趨勢（要求極低 Dk/Df 材料）。\n- (B) 朝 Low Tg 點發展：錯誤（正確答案，技術趨勢必然為 High Tg）。\n- (C) 低縱橫比結構設計：非技術阻礙，但 HDI 與載板朝微小盲孔與高縱橫比通孔兼備演進。\n- (D) 朝更精細且密度更高線路：主流 HDI/mSAP 趨勢。",
