    "stem": "除非特別必要，一般電路板都採對稱設計的主要考慮因素為何？",
    "question": "除非特別必要，一般電路板都採對稱設計的主要考慮因素為何？",
    "options": [
      "符合對稱壓合作業需求且比較不易板彎板翹",
      "只有半導體載板才需要",
      "比較省材料",
      "電路板業界習性"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】多層板對稱疊構（Symmetrical Lay-up）與熱應力翹曲控制。\n【正確答案說明】(A) 多層電路板在熱壓合（Lamination）及後續高溫迴焊時，樹脂會經歷液化流動、膠化與固化交聯，冷卻時會產生熱收縮應力。如果疊層結構不對稱（如芯板分佈不對稱、PP膠片厚度不對稱或銅箔殘銅率上下不平衡），中性面兩側產生的熱應力力矩無法相互抵消，板子會產生嚴重的「板彎板翹（Bow & Twist）」，無法通過平整度允收標準。因此電路板設計採對稱疊層，核心考慮是「符合對稱壓合作業需求且比較不易板彎板翹」。故選 A。\n【選項辨析】\n- (A) 符合對稱壓合作業需求且比較不易板彎板翹：正確。結構對稱能平衡層間熱應力，防止形變。\n- (B) 只有半導體載板才需要：一般所有多層 PCB 皆強烈要求對稱結構。\n- (C) 比較省材料：材料用量相同，無關節省材料。\n- (D) 電路板業界習性：背後是嚴謹的材料力學應力對稱原理，非無端習性。",
