    "stem": "在多層電路板的製造中，會使用全減除法製作線路，其相關的特性不包含下列 何 者？",
    "question": "在多層電路板的製造中，會使用全減除法製作線路，其相關的特性不包含下列 何 者？",
    "options": [
      "形成線路全程以蝕刻方式作業",
      "製程比線路電鍍方法複雜",
      "雙面板以上時常使用全板(Panel)電鍍",
      "細線路的製作與尺寸控制能力略差"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】全減除法（Subtractive Process）製程複雜度與線路製作特性。\n【正確答案說明】(B) 全減除法（Subtractive Method，又稱 Tent & Etch 覆膜蝕刻法）是電路板歷史最悠久、工序最精簡的傳統工法：貼膜→曝光→顯影→直接蝕刻去膜成型。相較於「線路電鍍法（Pattern Plating / 二次銅法，需先鍍乾膜圖案銅再鍍抗蝕錫，去膜後蝕刻再剝錫）」以及半加成法（mSAP），減除法的製程流程明顯「比線路電鍍方法更簡單、步驟更少」，而不是更複雜。故 (B) 稱全減除法比線路電鍍法複雜是錯誤的。\n【選項辨析】\n- (A) 形成線路全程以蝕刻方式作業：敘述正確（直接咬除大面積無阻劑銅箔）。\n- (B) 製程比線路電鍍方法複雜：錯誤（正確答案，減除法比線路電鍍二次銅法更簡短簡單）。\n- (C) 雙面板以上時常使用全板電鍍（Panel Plating）：敘述正確（先全板電鍍再覆膜蝕刻）。\n- (D) 細線路製作與尺寸控制能力略差：敘述正確（厚面銅側蝕嚴重，蝕刻因子低）。",
