    "explanation": "【核心考點】高階 HDI 雷射盲孔（Laser Blind Via）孔底殘膠與電鍍可靠度管制。\n【正確答案說明】(A) 雷射成孔打穿絕緣介質層到達靶銅面時，盲孔底部銅墊表面必須「100% 絕對潔淨無殘膠」。若盲孔底部殘留微量碳化樹脂膠渣（Smear），雖然化學銅或電鍍銅可能在孔壁四周爬覆，但孔底與底銅之間存在絕緣阻抗層，在後續 SMT 高溫熱應力衝擊下，孔底金屬介面會因結合力極差而全面開裂脫離（Via Separation / Post Failure），導致災難性的信號開路斷線。因此盲孔底部有殘膠「絕對屬於致命缺陷、嚴格拒收」，絕不可允收！故 (A) 敘述有誤。\n【選項辨析】\n- (A) 盲孔底部有殘膠仍可允收：錯誤（正確答案，屬於重大致命缺陷，嚴格拒收）。\n- (B) 打孔後須走孔底清潔流程（除膠與微蝕）：敘述正確（確保孔底金屬間原子鍵結）。\n- (C) 下孔徑管控在上孔徑 80% 以上：敘述正確（防止嚴重倒錐孔導致填孔空洞）。\n- (D) 管控盲孔是否孔偏：敘述正確（防止偏出靶墊破盤）。",
