    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】化鎳浸金（ENIG）與有機保焊膜（OSP）特性之精準對比。\n【正確答案說明】(D) 金（Au）是標準電極電位最高、熱力學最穩定且表面不生成氧化物的惰性貴金屬，對比其他所有金屬表面處理（化學錫、化學銀、OSP），金層具備最頂級卓越的「抗氧化能力」與長效保存壽命。\n【選項辨析】\n- (A) 化金焊接時在錫金介面形成 IMC：錯誤（金層瞬間熔入錫中，介面 IMC 為錫與鎳反應之 Ni3Sn4，非金錫介面 IMC）。\n- (B) 兩者皆可保護底下的鎳層：錯誤（OSP 是直接塗在銅面上，無底層鎳）。\n- (C) OSP 亦可保護非焊接區作為長期接觸導通：錯誤（OSP 為絕緣有機膜且易老化，無法作為插拔接觸點）。\n- (D) 金層對比其它鍍層是最具抗氧化的功能：正確。金層化學惰性最強，極耐氧化。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
