    "stem": "下列何者不會影響電路板的特性阻抗？",
    "question": "下列何者不會影響電路板的特性阻抗？",
    "options": [
      "介質層厚度與介電係數",
      "線寬",
      "線路長度",
      "面銅(電鍍銅與底銅總銅厚)銅厚度"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】高頻傳輸線特性阻抗（Zo）之無關幾何因子辨析。\n【正確答案說明】(C) 特性阻抗（Characteristic Impedance, Zo）的定義為電磁波沿傳輸線傳播時，瞬間電壓波與電流波之比值：Zo = √(L / C)，其中 L 與 C 分別為「單位長度的分佈電感與分佈電容」。\n分佈電容與電感完全取決於傳輸線的「橫斷面二維幾何尺寸與介質物性」（介質厚度 H、介電常數 Dk、線寬 W、銅厚 T）。只要橫截面尺寸維持均勻一致，特性阻抗的大小「與傳輸線的總長度（Trace Length）毫無關係」（長度只會影響信號傳輸延遲時間與信號衰減損失，不改變特性阻抗值）。故選 C。\n【選項辨析】\n- (A) 介質層厚度與介電係數：核心決定因子。\n- (B) 線寬：核心決定因子。\n- (C) 線路長度：正確答案（阻抗由橫截面分佈參數決定，與長度無關）。\n- (D) 面銅銅厚度：直接影響導體截面形狀。",
