    "stem": "有關硬板的線路蝕刻製程選項，下列何者有誤？",
    "question": "有關硬板的線路蝕刻製程選項，下列何者有誤？",
    "options": [
      "電漿蝕刻",
      "鹼性蝕刻",
      "酸性蝕刻",
      "快速蝕刻"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】剛性硬板工業化線路蝕刻工法分類與電漿限制。\n【正確答案說明】(A) 印刷電路板產業的線路圖案蝕刻（Pattern Etching）均為大量化學濕製程：\n- 鹼性蝕刻（氯化銅氨水體系）：外層線路電鍍二次銅錫製程的主流蝕刻液（不溶金屬錫保護層）；\n- 酸性蝕刻（酸性三氯化鐵或酸性氯化銅）：內層覆膜蝕刻的主要藥水（蝕刻速率快且容易再生）；\n- 快速蝕刻（Flash Etching / Differential Etching）：半加成法中快速咬除薄晶種底銅。\n而「電漿蝕刻（Plasma Etching）」為乾式真空氣相製程，僅能微量蝕刻去除高分子聚合物（如 PI/環氧除膠渣），無法大規模高效咬蝕厚達數微米至數十微米的金屬銅箔，業界絕無用於硬板線路蝕刻。故 (A) 敘述有誤。\n【選項辨析】\n- (A) 電漿蝕刻：錯誤（正確答案，非電路板金屬線路蝕刻選項）。\n- (B) 鹼性蝕刻：外層圖案電鍍二次銅標準蝕刻藥水。\n- (C) 酸性蝕刻：內層減除法標準蝕刻藥水。\n- (D) 快速蝕刻：mSAP 差分快速咬除晶種銅工藝。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
