    "stem": "下列傳統蝕刻減層法的雙面板流程何者正確？",
    "question": "下列傳統蝕刻減層法的雙面板流程何者正確？",
    "options": [
      "發料→鑽孔→電鍍→線路→防焊→化金→文字→外型→電測→外觀終檢",
      "發料→鑽孔→電鍍→線路→化金→防焊→文字→外型→電測→外觀終檢",
      "發料→鑽孔→電鍍→線路→防焊→化金→文字→電測→外型 CNC Routing→外 觀終檢",
      "發料→鑽孔→電鍍→線路→化金→防焊→文字→電測→外型→外觀終檢"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】傳統雙面板減除法（Double-Sided Subtractive）標準完整工藝流程。\n【正確答案說明】(A) 傳統減除法雙面板（PTH 金屬化雙面貫孔板）之經典標準製程時序如下：\n1. 發料（開料）→ 2. 鑽孔（成通孔）→ 3. 電鍍（全板化學沉銅 + 全板電鍍銅增厚孔壁）→ 4. 線路（壓膜、曝光、顯影、蝕刻、去膜形成線路圖案）→ 5. 防焊（網印液態感光阻焊漆、曝光、顯影、後烘固化）→ 6. 化金（ENIG 表面處理，露銅焊墊鍍金）→ 7. 文字（網印標識標記符號）→ 8. 外型加工（CNC Routing 成型銑切外框）→ 9. 電測（開短路測試）→ 10. 外觀終檢（FQC 檢驗與真空包裝）。\n外型加工在電測之前完成，便於治具快速精確靠位測試；化金必須在防焊之後進行，以防焊漆作為防鍍阻劑。故 (A) 流程完全正確。\n【選項辨析】\n- (A) 發料→鑽孔→電鍍→線路→防焊→化金→文字→外型→電測→外觀終檢：正確。\n- (B) 先化金再防焊：顛倒，會造成整條線路鍍金浪費且防焊附著力不良。\n- (C) 電測在外型之前：雙面板通常成型單片後上電測機專用治具測試。\n- (D) 多處工序顛倒矛盾。",
