    "stem": "印刷電路板主要由金屬導體與絕緣材料所組成， 有關對電路板使用的絕緣材料敘 述，下列何者有誤？",
    "question": "印刷電路板主要由金屬導體與絕緣材料所組成， 有關對電路板使用的絕緣材料敘 述，下列何者有誤？",
    "options": [
      "可分為有機與無機材料兩類",
      "一般電路板常使用的絕緣材料為有機材料",
      "硬性電路板常使用的絕緣材料是由環氧樹脂/玻璃纖維布所組成",
      "軟性電路板所使用的絕緣材料是酚醛樹脂(Phenolic Resin)"
    ],
    "answer": "D",
    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】印刷電路板絕緣材料類別與軟板基材高分子本質。\n【正確答案說明】(D) 軟性電路板（FPC）所使用的核心絕緣基材薄膜為「聚醯亞胺（Polyimide, PI）」或聚酯（PET，僅用於低階薄膜開關），具有高達 300~400°C 的極佳耐熱性與優良耐彎折性；而「酚醛樹脂（Phenolic Resin，如紙質基板 FR-1、FR-2）」是紙基硬質電路板所使用的早期廉價脆性材料，質地極為堅硬脆弱、完全不具備彎曲撓折性能，絕對不可能作為軟板的絕緣材料。故 (D) 敘述錯誤。\n【選項辨析】\n- (A) 可分為有機與無機材料兩類：敘述正確（有機如樹脂，無機如陶瓷/玻纖/填料）。\n- (B) 一般電路板常使用的絕緣材料為有機材料：敘述正確（高分子聚合物為主）。\n- (C) 硬性電路板常用絕緣材料由環氧樹脂/玻璃纖維布組成：敘述正確（即 FR-4）。\n- (D) 軟性電路板使用的絕緣材料是酚醛樹脂：錯誤（正確答案，軟板為 PI，非酚醛樹脂）。",
