    "stem": "有關印刷電路板的熱壓合製程，下列流程何者正確？",
    "question": "有關印刷電路板的熱壓合製程，下列流程何者正確？",
    "options": [
      "銅面黑/棕化→堆疊→鉚合→熱壓→冷壓",
      "銅面黑/棕化→鉚合→堆疊→熱壓→冷壓",
      "堆疊→銅面黑/棕化→鉚合→熱壓→冷壓",
      "銅面黑/棕化→鉚合→堆疊→冷壓→熱壓"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】多層板熱壓合（Lamination）之標準前處理與成型製程時序。\n【正確答案說明】(B) 多層板壓合的核心前置作業與熱壓循環工序如下：\n1. 銅面黑/棕化（Oxidation）：將內層芯板銅面氧化粗化，產生微觀針狀結晶以提供後續樹脂滲入之微觀錨定結合力；\n2. 鉚合（Riveting / Eyeletting / Pinning）：將經過棕化處理的內層芯板與半固化膠片（PP）透過定位鉚釘或雷射熔焊預先對位固定成疊板單元，防止層間滑移；\n3. 堆疊（Lay-up / Book Lay-up）：在鋼板、牛皮紙與鏡面板之間整齊堆疊多本板單元；\n4. 熱壓（Hot Pressing）：在高溫高壓與真空環境下使膠片樹脂熔融流動、排氣並充分交聯固化；\n5. 冷壓（Cold Pressing）：在保壓狀態下冷卻降溫至常溫，消除熱應力防止板翹。\n因此標準工序為：銅面黑/棕化 → 鉚合 → 堆疊 → 熱壓 → 冷壓。故 (B) 正確。\n【選項辨析】\n- (A) 先堆疊再鉚合：順序顛倒（需先單元鉚合定位再多本堆疊）。\n- (B) 銅面黑/棕化→鉚合→堆疊→熱壓→冷壓：正確。\n- (C) 先堆疊再銅面黑化：內層堆合後無法進入氧化藥水槽，邏輯錯誤。\n- (D) 先冷壓再熱壓：冷卻不可能在加熱之前，熱力學順序顛倒。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
