    "assessmentContent": "歷屆",
    "num": 23,
    "display_num": 23,
    "pdf_num": 23,
    "stem": "為降低材料的熱膨脹係數及提高產品的可靠度 ， 通常會利用加入下列何種材料來提 升材料的表現？",
    "question": "為降低材料的熱膨脹係數及提高產品的可靠度 ， 通常會利用加入下列何種材料來提 升材料的表現？",
    "options": [
      "無機材料",
      "銀膠",
      "銅粉",
      "環氧樹酯"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】高階基材填料（Filler）改性技術：降低 CTE 與提升尺寸安定性。\n【正確答案說明】(A) 環氧樹脂等有機高分子受熱時其分子鏈熱膨脹係數極大（CTE > 50~80 ppm/°C）。為了顯著降低基材在 Z 軸與平面方向的 CTE、提高熱尺寸穩定性並匹配矽晶圓或銅箔膨脹係數，現代電路板基板廠在樹脂配方中大量添加微米級甚至次微米級的「無機填料（Inorganic Fillers，如微粉化球形二氧化矽 SiO2、氧化鋁 Al2O3 或氫氧化鋁 ATH）」。無機填料熱膨脹率極低且耐熱，能大幅降低總體 CTE 並提高產品可靠度。故選 A。\n【選項辨析】\n- (A) 無機材料：正確。添加球型二氧化矽等無機填料是降低基板 CTE 之標準核心手段。\n- (B) 銀膠：導電接著劑，不可混入絕緣層中（會導致相鄰短路）。\n- (C) 銅粉：金屬導電材料，加入絕緣基板會破壞絕緣。\n- (D) 環氧樹脂：為基底聚合物本體，自身 CTE 高，需靠填料降低。",
