    "num": 28,
    "display_num": 28,
    "pdf_num": 28,
    "stem": "高密度互連技術(high-density-interconnection technology， HDI)印刷電路板廣泛使用 微孔(micro-via)技術，微孔可藉由機械鑽孔或雷射鑽孔製作。目前雷射鑽孔已逐漸 取代機械鑽孔方式，下列何者不是雷射鑽孔取代機械鑽孔的主要原因？",
    "question": "高密度互連技術(high-density-interconnection technology， HDI)印刷電路板廣泛使用 微孔(micro-via)技術，微孔可藉由機械鑽孔或雷射鑽孔製作。目前雷射鑽孔已逐漸 取代機械鑽孔方式，下列何者不是雷射鑽孔取代機械鑽孔的主要原因？",
    "options": [
      "微孔數量相當多，使用雷鑽較有效率",
      "機械鑽針製作需特殊合金如鈷、鎢等，稀有金屬日漸減少，故單價提高，同時雷 射燒孔等技術成熟，單價下降",
      "機械鑽孔無法達到高深寬比(aspect ratio)能力",
      "雷射鑽孔相較於機械鑽孔可產生更小的孔徑"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】高密度互連（HDI）雷射鑽孔（Laser Drilled Micro-via）技術優勢與深寬比限制。\n【正確答案說明】(C) 機械微鑽針在加工直徑小於 0.15 mm（150 μm）的極細微孔時，極易發生斷針、排屑阻塞與孔壁嚴重撕裂，因而被高能量光子束的雷射成孔（CO2 或 UV 雷射）取代。但必須注意：機械鑽孔在通孔加工中能輕易實現大於 10:1 至 20:1 的「超高深寬比（Aspect Ratio）」，而雷射成孔（Blind Micro-via）受限於高斯光束發散角與孔底光能量衰減，其深寬比通常僅在 0.8:1 至 1:1 左右（孔深大於孔徑時極難排膠與電鍍填孔）。因此宣稱「機械鑽孔無法達到高深寬比」是完全背離實務的錯誤認知。故選 C。\n【選項辨析】\n- (A) 微孔數量龐大雷鑽更有效率：正確（雷射打孔速率可達數百至上千孔/秒）。\n- (B) 機械鑽針稀有鎢鈷合金昂貴且易損耗，雷射燒孔技術成熟單價下降：正確。\n- (C) 機械鑽孔無法達到高深寬比能力：錯誤（正確答案，機械鑽孔是實現超高縱橫比深通孔的強項工法）。\n- (D) 雷射相較於機械可產生更小的微孔徑（< 100 μm）：正確。",
    "source_id": "pcb-8f595b7986615df2",
