    "explanation": "【核心考點】低階 PCB 鑽孔孔壁金屬化工藝清單辨析。\n【正確答案說明】(B) 印刷電路板普通低階雙面與多層板鑽孔後，為了讓絕緣樹脂與玻纖孔壁形成導電層以利後續電鍍，工業上常用的孔壁金屬化工藝包含：\n1. 化學沉銅（PTH / Electroless Copper）；\n2. 碳黑直接電鍍法（黑孔 Black Hole）；\n3. 石墨膠體直接電鍍法（黑影 Shadow）。\n而「棕化（Brown Oxide）」是多層板在壓合之前，為了增加內層銅面與環氧樹脂結合力所進行的化學微粗化氧化處理工藝，完全與鑽孔後的孔壁導電化無關。故選 B。\n【選項辨析】\n- (A) 黑影：石墨導電化直接電鍍工藝。\n- (B) 棕化：正確答案（多層板內層壓合前處理，非孔壁金屬化技術）。\n- (C) 黑孔：碳黑導電化直接電鍍工藝。\n- (D) 化學銅：傳統化學沉銅金屬化。",
