    "ans_text": "標準答案：(D)",
    "is_multiple": false,
    "explanation": "【核心考點】內層線路乾膜壓膜前處理之標準化學清洗工序。\n【正確答案說明】(D) 內層線路製作前，銅箔基板必須徹底去除防氧化油劑、整平並建立微觀粗化峰谷以利乾膜黏著。標準前處理化學工序順序必須為：\n1. 「脫脂（Degreasing / Acid Cleaner）」：清除表面油脂、指紋與微塵；\n2. 「水洗」；\n3. 「微蝕粗化（Micro-etch）」：利用氧化酸液咬蝕銅面數十微英吋，形成新鮮粗糙表面；\n4. 「酸洗（Acid Rinse）」：洗除銅表面微蝕殘留氧化皮膜；\n5. 「乾燥（Drying）」：以熱風徹底烘乾水分送入壓膜機。\n若如 (D) 所述「脫脂 → 乾燥 → 粗化」，在乾燥後再粗化不僅破壞乾燥，且粗化後未烘乾無法貼膜，工序完全顛倒錯亂。故 (D) 敘述有誤。\n【選項辨析】\n- (A) 基板交貨有防氧化層開工前需先去除：敘述正確（抗氧化鈍化膜需脫脂酸洗咬除）。\n- (B) 前處理有機械刷磨與化學微蝕兩種：敘述正確。\n- (C) 塗佈光阻前必須前處理以提高結合力：敘述正確（防止顯影斷線與滲鍍）。\n- (D) 基本程序為脫脂→乾燥→粗化：錯誤（正確答案，乾燥必然在粗化水洗之後的最末步驟）。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-243d694d0ee81e9284202860",
    "content_hash": "c3f152356e3f803238ab8fe919dca2cb611b14f9b5105945a6a3dc1b99aa8902",
    "id": 120
