    "pdf_num": 32,
    "stem": "利用在基板內部重新佈線，將 IC 和此基板連結，並透過它再與 PCB 連結，這種板 子稱為下列何者？",
    "question": "利用在基板內部重新佈線，將 IC 和此基板連結，並透過它再與 PCB 連結，這種板 子稱為下列何者？",
    "options": [
      "IC 載板",
      "排線",
      "軟硬板",
      "Embedded PCB"
    ],
    "answer": "A",
    "ans_text": "標準答案：(A)",
    "is_multiple": false,
    "explanation": "【核心考點】半導體封裝載板（IC Substrate）之定義與核心功能定位。\n【正確答案說明】(A) IC 載板（IC Substrate / 半導體封裝基板）是介於奈米級半導體裸晶片（Die）與微米級傳統印製電路板（PCB）之間的微細互連橋樑。載板內部具備高密度超微細微佈線（L/S < 10/10 μm）、微盲孔及倒裝焊墊，晶片透過覆晶（Flip Chip）或打線直接焊接在其上，再透過載板底部的球柵陣列（BGA 錫球）與系統主 PCB 互相連結。這種特化的高階電路板即稱為「IC 載板」。故選 A。\n【選項辨析】\n- (A) IC 載板：正確。承接裸晶片與系統主板之高階封裝基板。\n- (B) 排線：單純導線互連元件。\n- (C) 軟硬板：結合軟板與硬板之電路板，非半導體封裝載板。\n- (D) Embedded PCB：內埋被動或主動元件之多層板。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-60fc976d7830a788689dfbe7",
    "content_hash": "ee9281b011002525c9af5aa7a7d4f08624d491c6a2224f3fe6fab466e63f24af",
