    "num": 33,
    "display_num": 33,
    "pdf_num": 33,
    "stem": "有關整板電鍍(panel plating)鍍銅層厚度之敘述，下列何者正確？",
    "question": "有關整板電鍍(panel plating)鍍銅層厚度之敘述，下列何者正確？",
    "options": [
      "電流密度固定之下，機台設定時估算的電鍍面積小於實際板子面積會造成鍍銅 層太厚",
      "電流密度固定之下，機台設定時估算的電鍍面積大於實際板子面積會造成鍍銅 層太厚",
      "電流密度固定之下，機台設定時估算的電鍍面積與實際板子面積差異不會影響 鍍銅層厚度",
      "電鍍掛架接觸不良會造成鍍銅層太厚"
    ],
    "answer": "B",
    "ans_text": "標準答案：(B)",
    "is_multiple": false,
    "explanation": "【核心考點】整板電鍍（Panel Plating）面積設定偏差對鍍銅厚度之影響。\n【正確答案說明】(B) 在自動電鍍設備中，整板電鍍電流設定公式為：總電流 I_total = 設定電流密度 J_set × 輸入之電鍍面積 A_input。\n若工程師在機台設定時「估算的電鍍面積大於實際板子面積」（即 A_input > A_actual），設備輸出的總電流 I_total 會遠高於實際所需電流。當這股過大電流灌入較小面積的板子上時，板面上的「實際電流密度 J_actual = I_total / A_actual 會顯著高於預設目標值」。在相同的電鍍時間下，依據法拉第定律，沉積在板上的「鍍銅層厚度會太厚（超厚）」。故 (B) 敘述正確。\n【選項辨析】\n- (A) 估算面積小於實際面積會造成太厚：相反（估算偏小總電流不足，鍍層會偏薄）。\n- (B) 估算電鍍面積大於實際板子面積會造成鍍銅層太厚：正確。\n- (C) 面積差異不會影響鍍層厚度：嚴重錯誤（電流密度改變直接決定厚度）。\n- (D) 電鍍掛架接觸不良會造成太厚：相反（接觸不良阻抗大，分流不足鍍層偏薄）。",
