    "stem": "印刷電路板壓合後，下列何種儀器無法確認材料玻璃轉化溫度(Tg)？",
    "question": "印刷電路板壓合後，下列何種儀器無法確認材料玻璃轉化溫度(Tg)？",
    "options": [
      "DSC",
      "DMA",
      "TGA",
      "TMA"
    ],
    "answer": "C",
    "ans_text": "標準答案：(C)",
    "is_multiple": false,
    "explanation": "【核心考點】熱分析儀器功能範疇：無法量測玻璃轉化溫度（Tg）之儀器。\n【正確答案說明】(C)\n- 能確認量測材料玻璃轉化溫度（Tg）的熱分析儀器包括：\n  1. DSC（熱示差掃描量熱儀）：量測玻璃轉化吸熱台階；\n  2. TMA（熱機械分析儀）：量測熱膨脹曲線斜率反折轉折點；\n  3. DMA（動態熱機械分析儀）：量測損耗模數或損耗角正切（Tan δ）峰值。\n- TGA（Thermogravimetric Analysis，熱重分析儀）：主要用於量測材料高溫熱裂解時的「質量重量損失（Weight Loss）」，用以測定熱裂解溫度（Td）與灰分無機含量，在材料尚未裂解失重前（如 Tg 溫度區間 150~200°C 內）樣品重量完全沒有任何改變，因此「TGA 無法確認量測玻璃轉化溫度（Tg）」。故選 C。\n【選項辨析】\n- (A) DSC：量測 Tg 標準儀器之一。\n- (B) DMA：量測 Tg 靈敏度最高之動態熱分析儀。\n- (C) TGA：正確答案（量測重量損失與 Td，完全無法測量 Tg）。\n- (D) TMA：量測熱膨脹斜率反轉確認 Tg 之工業標準方法。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
