    "explanation": "【核心考點】銅箔重量厚度換算基準中「面積基準單位」之辨析。\n【正確答案說明】(C) 國際標準銅箔厚度換算法則中，1 盎司（oz）銅箔厚度（約 34~35 μm）的法定計算基礎是將 28.35 公克的銅均勻鋪展在「每平方英尺（1 square foot = 1 ft²）」的面積上，絕對不是每平方英吋（Square Inch）！若鋪在 1 平方英吋上，其厚度將高達 144 倍（近 5 毫米厚）。故 (C) 稱按每平方英吋作計算是錯誤的。\n【選項辨析】\n- (A) 1 oz 銅厚度大約是 34~35 μm：敘述正確。\n- (B) 1 oz 是用 28.35 公克換算：敘述正確（1 常衡盎司 = 28.3495 g）。\n- (C) 面積是按每平方英寸來計算：錯誤（正確答案，應為每平方英尺 ft²）。\n- (D) 銅箔密度以 8.93 g/cm³ 計算：敘述正確（純金屬銅密度標準常數）。",
