    "pdf_num": 1,
    "stem": "印刷電路板必須提供的主要功能有下列哪些？",
    "question": "印刷電路板必須提供的主要功能有下列哪些？",
    "options": [
      "耐熱、高強度",
      "低電阻",
      "層線間絕緣性",
      "可組裝焊接性"
    ],
    "answer": "ABCD",
    "ans_text": "標準答案：(ABCD)",
    "is_multiple": true,
    "explanation": "【核心考點】印刷電路板（PCB）提供電子系統運作之四大根本功能。\n【正確答案說明】(ABCD) 印刷電路板作為電子元器件之物理載體與電氣神經中樞，必須同時提供以下關鍵功能：\n- (A) 耐熱、高強度：承受高溫無鉛焊接熱應力與機構抗振支撐（正確）；\n- (B) 低電阻：銅線路需提供極低傳輸電阻以降低發熱與傳輸信號損耗（正確）；\n- (C) 層線間絕緣性：絕緣樹脂基材與阻焊層必須提供優異之高壓耐壓與高兆歐級絕緣阻抗（正確）；\n- (D) 可組裝焊接性：表面處理焊墊需提供優良的潤濕性與低空洞率焊接能力（正確）。\n四者皆為 PCB 核心機能。故選 ABCD。\n【選項辨析】\n- (A) 正確：結構剛性與耐組裝熱衝擊。\n- (B) 正確：電氣能量與信號高效傳導。\n- (C) 正確：相鄰信號與高壓走線間電氣隔離。\n- (D) 正確：SMT 元件與接插件良好接合。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-d697e50a5b09125a8cfaab29",
    "content_hash": "121690fd4cf9a1af4d10d3c8f9c068f8f71001b1b1bc6b0777b57e5ee9293065",
