    "num": 37,
    "display_num": 37,
    "pdf_num": 2,
    "stem": "下列哪些材料是硬板用來遮蔽保護防止特定銅面在迴焊或波焊製程中接觸到焊 錫？",
    "question": "下列哪些材料是硬板用來遮蔽保護防止特定銅面在迴焊或波焊製程中接觸到焊 錫？",
    "options": [
      "DFSR 乾膜式防焊阻劑",
      "防焊油墨",
      "OSP 區",
      "化金區"
    ],
    "answer": "AB",
    "ans_text": "標準答案：(AB)",
    "is_multiple": true,
    "explanation": "【核心考點】硬質電路板外層防焊遮蔽材料型式。\n【正確答案說明】(AB) 在硬板（Rigid PCB）製程中，用來遮蔽保護線路、防止非焊接區在迴焊或波焊中沾錫短路的防焊材料主要有兩種：\n1. (A) DFSR（Dry Film Solder Resist）：乾膜式防焊阻劑，膜厚高度均勻，無邊緣變薄問題，常用於 IC 載板或高密度平整度板；\n2. (B) 防焊油墨（Liquid Photoimageable Solder Mask, LPI / PSR）：業界最普遍之液態感光防焊綠漆。\nOSP 區與化金區是已經開窗露銅、專門用來接受焊錫接合的表面處理金屬導電層，絕非遮蔽阻焊材料。故選 AB。\n【選項辨析】\n- (A) DFSR 乾膜式防焊阻劑：正確。高平整度乾膜防焊材料。\n- (B) 防焊油墨：正確。傳統且主流之防焊綠漆材料。\n- (C) OSP 區：為供焊接之露銅防焊開口區。\n- (D) 化金區：為供焊接之鍍金金屬墊。",
    "source_id": "pcb-8f595b7986615df2",
