    "stem": "下列哪些因素與成品板厚不相關？",
    "question": "下列哪些因素與成品板厚不相關？",
    "options": [
      "疊層所使用ＰＰ與銅箔材料的廠牌",
      "疊層所使用ＰＰ與銅箔材料的型號與厚度規格",
      "防焊油墨的廠牌",
      "壓合後的厚度管控"
    ],
    "answer": "AC",
    "ans_text": "標準答案：(AC)",
    "is_multiple": true,
    "explanation": "【核心考點】多層板成品總板厚規格之「不相關」因素辨析。\n【正確答案說明】(AC) 成品板厚的實質物理控制因素包含：內外層芯板厚度、銅箔厚度、PP膠片型號與實際膠含量含膠量（(B)）、壓合時的流膠量與厚度補償管制（(D)）。而材料的「廠牌（Brand Name）」，只要符合相同的規格厚度（如 1080 PP 壓出公稱 2.5 mil），其廠牌名稱本身並非影響厚度的技術參數（(A)不相關）；外層塗覆之防焊油墨無論何種「廠牌」，其標準塗覆乾膜厚度皆在 15~25 μm 控制範圍內，其廠牌名稱與板厚規格控制不相關（(C)不相關）。題目問哪些與成品板厚不相關，故答案為 AC。\n【選項辨析】\n- (A) PP與銅箔的廠牌：正確答案（非厚度決定物理因子，規格相同即可互換）。\n- (B) PP與銅箔的型號與厚度規格：直接決定厚度（高度相關）。\n- (C) 防焊油墨的廠牌：正確答案（廠牌名稱不影響規格設定）。\n- (D) 壓合後的厚度管控：直接控制最終實體厚度（高度相關）。",
