    "stem": "雷射成孔處理方式中之敘述，下列哪些正確？",
    "question": "雷射成孔處理方式中之敘述，下列哪些正確？",
    "options": [
      "開銅窗法需要先用線路蝕刻方式將銅箔開窗後再以 CO2 雷射去打絕緣層",
      "先將銅面進行黑/棕化後再用 CO2 雷射去打黑/棕化銅箔與絕緣層",
      "直接用 CO2 雷射去打銅箔與絕緣層",
      "可採混合 UV+CO2 雷射系統分別去打銅箔與絕緣層"
    ],
    "answer": "ABD",
    "ans_text": "標準答案：(ABD)",
    "is_multiple": true,
    "explanation": "【核心考點】高密度互連板雷射微孔（Laser Via）三大成孔技術工法。\n【正確答案說明】(ABD) 雷射成孔打穿銅箔與介質層的主流工法包含：\n- (A) 開銅窗法（Conformal Mask / Direct Etched Window）：先用線路蝕刻將表面銅箔咬出圓孔（開窗），再以對銅反射率高但極易被樹脂吸收的 CO2 雷射直接燒除窗口內的絕緣樹脂層（正確）；\n- (B) 大視場黑/棕化法（Coated Copper / Browned Copper）：先將外層極薄銅箔表面進行微粗化黑化或棕化處理，大幅提高銅面對紅外 CO2 雷射（波長 10.6 μm）的光吸收率，再直接以強脈衝 CO2 雷射一併打穿黑化銅箔與底層樹脂（正確）；\n- (D) 混合雷射工法（UV + CO2 Hybrid Laser）：利用短波長高光子能量的 UV 紫外線雷射（波長 355 nm）冷消融精確切穿頂層銅箔，隨後切換至大光斑高效率的 CO2 雷射迅速燒除底層樹脂，兼具高精度與高效率（正確）。\n(C) 未經表面微粗化氧化處理的天然光滑銅箔對紅外 CO2 雷射的光反射率高達 95% 以上，雷射能量會被全數反射彈開，根本無法直接打穿光滑銅箔。故選 ABD。\n【選項辨析】\n- (A) 正確：傳統開銅窗工法。\n- (B) 正確：黑化增加紅外吸收率直接打穿工法。\n- (C) 錯誤：光滑裸銅對 CO2 雷射反射率過高無法直打。\n- (D) 正確：先進 UV/CO2 雙光源混合成孔技術。",
    "source_id": "pcb-8f595b7986615df2",
    "source_version": "official-115-01",
    "question_uid": "pcb-6babb37c76d8519d5304c07a",
    "content_hash": "d2e74b5b5021ee384d9a5c73aba81392ec39c5391fda2c12a441ddb31f6fb2fb",
    "id": 129
