    "pdf_num": 5,
    "stem": "針對厚板小孔這種高縱橫比的通孔電鍍，欲使孔壁厚度達一定最小要求例如 20μm 以上時，須搭配下列哪些作業條件要求？",
    "question": "針對厚板小孔這種高縱橫比的通孔電鍍，欲使孔壁厚度達一定最小要求例如 20μm 以上時，須搭配下列哪些作業條件要求？",
    "options": [
      "降低銅電鍍的 Throwing Power (分佈力=孔壁電鍍厚度/面銅電鍍厚度)",
      "提升銅電鍍的 Throwing Power (分佈力=孔壁電鍍厚度/面銅電鍍厚度)",
      "調整藥水的酸銅比甚至於採用脈充電鍍",
      "當面銅太厚時搭配減銅作業達成細線路要求"
    ],
    "answer": "BCD",
    "ans_text": "標準答案：(BCD)",
    "is_multiple": true,
    "explanation": "【核心考點】高縱橫比深孔（High Aspect Ratio Via）通孔電鍍技術條件。\n【正確答案說明】(BCD) 在厚板小孔（如板厚 2.4 mm、孔徑 0.2 mm，縱橫比高達 12:1）電鍍中，孔中央深處的藥水對流交換極差、離子耗竭劇烈，極易產生啞鈴狀（孔口厚、孔中央無銅）電鍍缺陷：\n- (B) 提升 Throwing Power（電鍍分散能力 / 分佈力）：電鍍分散能力定義為「孔壁中央電鍍厚度 / 面銅電鍍厚度」，必須將分散力提高至 80%~100% 以上，確保孔壁達到 20 μm 時面銅不過度過厚（正確）；\n- (C) 調整酸銅比與脈充電鍍：採用高酸低銅藥水體系（高硫酸濃度提升導電度，低硫酸銅濃度降低離子擴散阻力），並導入週期換向脈充電鍍（PPR, Periodic Pulse Reverse），大幅消除微孔擴散極化（正確）；\n- (D) 減銅作業搭配細線路：若為了確保孔壁銅厚導致面銅電鍍過厚（> 35 μm）無法製作微細線路時，需搭配面銅微減銅（Etch-back / Planarization）研磨工序（正確）。\n(A) 宣稱降低分佈力是完全相反的破壞性操作。故答案為 BCD。\n【選項辨析】\n- (A) 錯誤：降低分佈力會導致孔壁無銅破孔。\n- (B) 正確：核心關鍵在於極大化分佈力（Throwing Power）。\n- (C) 正確：高酸低銅配合脈衝電流是高厚徑比標準工藝。\n- (D) 正確：解決面銅過厚影響後續蝕刻的減銅工法。",
