    "pdf_num": 6,
    "stem": "印刷電路板製程的表面處理方式有許多種類，其中成本比較高的是鎳鈀金，有關 其作業原理與功能，下列哪些有誤？",
    "question": "印刷電路板製程的表面處理方式有許多種類，其中成本比較高的是鎳鈀金，有關 其作業原理與功能，下列哪些有誤？",
    "options": [
      "鈀沉積在鎳層的原理是鈀離子咬蝕鎳層直接在鎳表面進行沉積作用",
      "比 OSP 的儲存與保固期更長久",
      "適合 SMT 作業",
      "不適合晶片的打線作業"
    ],
    "answer": "AD",
    "ans_text": "標準答案：(AD)",
    "is_multiple": true,
    "explanation": "【核心考點】化學鎳鈀金（ENEPIG）表面處理原理與晶片打線適用性辨析。\n【正確答案說明】(AD)\n- (A) 敘述有誤（符合題意）：化學鎳鈀金中的「鈀層（Palladium）」沉積是採用含有化學還原劑的化學鍍液進行「自催化還原沉積（Autocatalytic Reduction）」，絕不是依靠鈀離子腐蝕咬蝕鎳層之置換反應！置換反應會破壞鎳晶界造成晶界腐蝕缺陷；\n- (D) 敘述有誤（符合題意）：ENEPIG 之所以被譽為萬用表面處理（Universal Finish），其最大優勢正是因為中間的純鈀層徹底消除了黑鎳隱患並阻擋鎳遷移，特別具備頂級卓越的「晶片打線能力（Wire Bonding，完全相容金線、鋁線及銅線打線）」。「不適合晶片打線作業」是顛倒事實的重大錯誤敘述。\n(B) 保存期長於 OSP、(C) 高度適合 SMT 皆為正確敘述。題目問哪些有誤，故選 AD。\n【選項辨析】\n- (A) 錯誤敘述（答案）：鈀層沉積為化學還原型自催化，非置換咬蝕。\n- (B) 正確敘述：耐儲存性極佳。\n- (C) 正確敘述：焊接可靠度極高。\n- (D) 錯誤敘述（答案）：ENEPIG 最核心的強項就是晶片打線（Wire Bonding）。",
