    "pdf_num": 7,
    "stem": "若某 6 層二階盲埋孔 PCB 的 Gerber File 資料出現鑽孔圖檔名稱為 L1-L2， L2- L3， L1-L3， L3-L4， L4-L5， L4-L6， L5-L6，有關此 PCB 的盲埋加工方式、 電鍍的次數與壓合的次數，下列哪些有誤？",
    "question": "若某 6 層二階盲埋孔 PCB 的 Gerber File 資料出現鑽孔圖檔名稱為 L1-L2， L2- L3， L1-L3， L3-L4， L4-L5， L4-L6， L5-L6，有關此 PCB 的盲埋加工方式、 電鍍的次數與壓合的次數，下列哪些有誤？",
    "options": [
      "此 PCB 為三次壓合加工",
      "L1-L3 為疊孔設計，分別是 L1-L2 與 L2-L3 盲孔互相堆疊",
      "此 PCB 為兩次電鍍加工",
      "此為兩次壓合加工"
    ],
    "answer": "BD",
    "ans_text": "標準答案：(BD)",
    "is_multiple": true,
    "explanation": "【核心考點】六層二階 HDI 盲埋孔板之壓合次數與疊孔結構工程辨析。\n【正確答案說明】(BD) 六層二階盲埋孔結構分析：\n- 壓合次數分析：\n  第 1 次壓合：壓製 L3-L4 內層核心板（Core），鑽 L3-L4 埋孔並電鍍；\n  第 2 次壓合：向外增層壓合 L2 與 L5，鑽 L2-L3、L4-L5（一階盲孔）並電鍍；\n  第 3 次壓合：再向外增層壓合 L1 與 L6，鑽 L1-L2、L5-L6（二階盲孔）並電鍍。\n  因此「該 PCB 為三次壓合加工（(A)正確）」、「(D)稱兩次壓合有誤」。\n- 盲孔設計分析：\n  若圖檔中出現「L1-L3」跨層鑽孔名稱，代表此二階盲孔採用的是直接雷射一槍貫穿 L1-L3 之「跨階階梯孔（Staggered / Stepped Via）」或一次深孔，而不是 L1-L2 與 L2-L3 上下疊合填平之「疊孔（Stacked Via，疊孔圖檔只需 L1-L2 與 L2-L3）」。故「(B)稱 L1-L3 為疊孔設計有誤」。\n題目問哪些敘述有誤，故答案為 BD。\n【選項辨析】\n- (A) 正確敘述：二階 HDI 標準為 3 次壓合（Core一次 + 兩次增層）。\n- (B) 錯誤敘述（答案）：L1-L3 跨層鑽孔非疊孔。\n- (C) 正確敘述：電鍍加工次數需配合階數（盲埋孔填孔電鍍）。\n- (D) 錯誤敘述（答案）：二階非兩次壓合。",
