    "pdf_num": 8,
    "stem": "硬板近來在行動通訊及 AI 產業的蓬勃發展，帶動包含高效運算、機器人、智慧製 造、自動駕駛及無人載具等的應用，因應此產業變化，其未來的技術發展趨勢有 下列哪些？",
    "question": "硬板近來在行動通訊及 AI 產業的蓬勃發展，帶動包含高效運算、機器人、智慧製 造、自動駕駛及無人載具等的應用，因應此產業變化，其未來的技術發展趨勢有 下列哪些？",
    "options": [
      "使用高頻高速的材料",
      "設計朝高密度細線路與高層數發展",
      "使用高膨脹系數(high CTE)材料",
      "使用 high Tg 材料"
    ],
    "answer": "ABD",
    "ans_text": "標準答案：(ABD)",
    "is_multiple": true,
    "explanation": "【核心考點】AI 伺服器與高算力時代剛性硬板材料三大演進方向。\n【正確答案說明】(ABD) AI 伺服器主板（UBB / OAM）、高階交換機與算力加速卡板層數高達 20~40 層以上，總功耗高達數百至上千瓦：\n- (A) 高頻高速材料：全面導入 Very Low Loss / Ultra Low Loss 等級低損耗銅箔基板（如 PTFE、改性聚苯醚 PPO/PPE），確保高速 PCIe 5.0/6.0 與 112G/224G SerDes 訊號完整性（正確）；\n- (B) 高密度細線路與高層數：背板與加速模組層數達 24~40 層，線路寬距向高密度微細化發展（正確）；\n- (D) High Tg 材料：多層厚板在迴焊與大功耗運行時熱應力巨大，基材 Tg 必須 ≥ 180~200°C 才能防止爆板（正確）。\n(C) 宣稱「使用高膨脹係數（High CTE）材料」是致命錯誤！高算力硬板必須嚴格追求「Low CTE（低熱膨脹係數）」，才能防止在 Z 軸熱膨脹拉斷微小導通孔（PTH 拉裂）並確保與晶片載板熱匹配。故選 ABD。\n【選項辨析】\n- (A) 正確：AI 高速傳輸必備低損耗材料。\n- (B) 正確：大算力互連結構必備超高層數與 HDI 密集走線。\n- (C) 錯誤：必須使用低熱膨脹係數（Low CTE）材料，高 CTE 會導致熱應力斷孔爆板。\n- (D) 正確：高耐熱 High Tg 是高多層板基礎門檻。",
