    "stem": "傳統蝕刻減層法的作業下採底片型曝光機作業時，如果發現線路過細的因素中， 可能為下列哪些因素？",
    "question": "傳統蝕刻減層法的作業下採底片型曝光機作業時，如果發現線路過細的因素中， 可能為下列哪些因素？",
    "options": [
      "曝光能量不足",
      "蝕刻速度過慢",
      "銅厚不均，薄銅區出現線細",
      "底片吸真空不良"
    ],
    "answer": "ABC",
    "ans_text": "標準答案：(ABC)",
    "is_multiple": true,
    "explanation": "【核心考點】減除法曝光顯影蝕刻（SES）線路過細（Under-width）之成因分析。\n【正確答案說明】(ABC) 在採用負型乾膜底片曝光的減除法製程中：\n- (A) 曝光能量不足：光化學聚合反應不充分，乾膜光阻交聯硬化寬度變窄、膜厚變薄，耐蝕刻邊緣侵蝕能力弱，導致蝕刻後線路變細（正確）；\n- (B) 蝕刻速度過慢：板材在蝕刻噴淋槽內停留時間過長（過度蝕刻 Over-etching），蝕刻液不僅向下咬銅更強烈向兩側橫向側蝕，造成線路嚴重過細（正確）；\n- (C) 銅厚不均，薄銅區出現線細：在統一的蝕刻時間下，局部偏薄的銅箔過早被咬透，後續時間全數轉化為橫向側蝕，導致薄銅區線路過細（正確）。\n(D) 底片吸真空不良會引起光暈繞射與散射，使不該曝光的區域部分曝光，乾膜變寬或殘膠，蝕刻後造成的是「線路變粗或短路」，而不是線路過細。故選 ABC。\n【選項辨析】\n- (A) 正確：光阻交聯不足邊緣回縮，蝕刻後線變細。\n- (B) 正確：過度蝕刻造成過度側蝕線細。\n- (C) 正確：薄銅區過度咬蝕引發線細。\n- (D) 錯誤：吸真空不良光線散射擴散，導致線路變粗或殘銅。",
