    "ans_text": "標準答案：(ACD)",
    "is_multiple": true,
    "explanation": "【核心考點】印刷電路板 FR-4 硬板銅箔基板（CCL）工業標準原材規格尺寸。\n【正確答案說明】(ACD) 國際銅箔基板廠（如生益、南亞、聯茂、台光電、台燿等）生產 FR-4 剛性覆銅基板（CCL Master Panel）時，最標準通用且被各大 PCB 廠裁切排版（Panelization）採用的基板常規原廠開料大板尺寸為：\n1. (A) 36 inch × 48 inch（或修邊 37 in × 49 in，約 914 mm × 1219 mm）；\n2. (C) 40 inch × 48 inch（或修邊 41 in × 49 in，約 1016 mm × 1219 mm）；\n3. (D) 42 inch × 48 inch（或修邊 43 in × 49 in，約 1067 mm × 1219 mm）。\n而 (B)「38 inch × 48 inch」並非 CCL 業界的常規標準板料生產模具尺寸。故常規尺寸為 ACD。\n【選項辨析】\n- (A) 36 in x 48 in：正確。CCL 業界三大最經典標準大板尺寸之一。\n- (B) 38 in x 48 in：非標準通用基板尺寸。\n- (C) 40 in x 48 in：正確。CCL 業界高利用率標準常規尺寸。\n- (D) 42 in x 48 in：正確。CCL 業界大型拼板常用標準尺寸。",
